                      className="hover:text-red-900"
                    >
                      <Trash2 className="h-3 w-3" />
                    </button>
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-2">
              <Label>Intolerancias</Label>
              <div className="flex gap-2">
                <Input
                  placeholder="Agregar intolerancia..."
                  value={newIntolerance}
                  onChange={(e) => setNewIntolerance(e.target.value)}
                  onKeyPress={(e) => {
                    if (e.key === 'Enter' && newIntolerance.trim()) {
                      addItem('eating_habits.intolerances', newIntolerance.trim());
                      setNewIntolerance('');
                    }
                  }}
                />
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    if (newIntolerance.trim()) {
                      addItem('eating_habits.intolerances', newIntolerance.trim());
                      setNewIntolerance('');
                    }
                  }}
                >
                  <Plus className="h-4 w-4" />
                </Button>
              </div>
              <div className="flex flex-wrap gap-2 mt-2">
                {formData.eating_habits.intolerances.map((intolerance, index) => (
                  <div key={index} className="flex items-center gap-1 bg-yellow-50 text-yellow-700 rounded-full px-3 py-1">
                    <span className="text-sm">{intolerance}</span>
                    <button
                      type="button"
                      onClick={() => removeItem('eating_habits.intolerances', index)}
                      className="hover:text-yellow-900"
                    >
                      <Trash2 className="h-3 w-3" />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        );

      case 6: // 24h Recall
        return (
          <div className="space-y-8">
            {/* Weekday */}
            <div>
              <h3 className="font-semibold mb-4">D├¡a de semana</h3>
              <div className="space-y-4">
                {[
                  { key: 'breakfast', label: 'Desayuno' },
                  { key: 'mid_morning', label: 'Media ma├▒ana' },
                  { key: 'lunch', label: 'Almuerzo' },
                  { key: 'snack', label: 'Merienda' },
                  { key: 'dinner', label: 'Cena' },
                ].map((meal) => (
                  <div key={meal.key} className="space-y-2">
                    <Label>{meal.label}</Label>
                    <Textarea
                      placeholder={`Describe lo que consume en ${meal.label.toLowerCase()}...`}
                      value={formData.recall_24h.weekday[meal.key as keyof typeof formData.recall_24h.weekday]}
                      onChange={(e) => updateFormData(`recall_24h.weekday.${meal.key}`, e.target.value)}
                    />
                  </div>
                ))}
              </div>
            </div>

            {/* Weekend */}
            <div>
              <h3 className="font-semibold mb-4">Fin de semana</h3>
              <div className="space-y-4">
                {[
                  { key: 'breakfast', label: 'Desayuno' },
                  { key: 'mid_morning', label: 'Media ma├▒ana' },
                  { key: 'lunch', label: 'Almuerzo' },
                  { key: 'snack', label: 'Merienda' },
                  { key: 'dinner', label: 'Cena' },
                ].map((meal) => (
                  <div key={meal.key} className="space-y-2">
                    <Label>{meal.label}</Label>
                    <Textarea
                      placeholder={`Describe lo que consume en ${meal.label.toLowerCase()}...`}
                      value={formData.recall_24h.weekend[meal.key as keyof typeof formData.recall_24h.weekend]}
                      onChange={(e) => updateFormData(`recall_24h.weekend.${meal.key}`, e.target.value)}
                    />
                  </div>
                ))}
              </div>
            </div>
          </div>
        );

      case 7: // Lab Results
        return (
          <div className="space-y-6">
            <div className="space-y-2">
              <Label>An├ílisis cl├¡nicos</Label>
              {formData.lab_results.map((result, index) => (
                <div key={index} className="flex gap-2 items-start">
                  <Input
                    placeholder="Nombre del an├ílisis"
                    value={result.test_name}
                    onChange={(e) => {
                      const newResults = [...formData.lab_results];
                      newResults[index].test_name = e.target.value;
                      updateFormData('lab_results', newResults);
                    }}
                  />
                  <Input
                    placeholder="Valor"
                    value={result.value}
                    onChange={(e) => {
                      const newResults = [...formData.lab_results];
                      newResults[index].value = e.target.value;
                      updateFormData('lab_results', newResults);
                    }}
                    className="w-24"
                  />
                  <Input
                    placeholder="Unidad"
                    value={result.unit}
                    onChange={(e) => {
                      const newResults = [...formData.lab_results];
                      newResults[index].unit = e.target.value;
                      updateFormData('lab_results', newResults);
                    }}
                    className="w-24"
                  />
                  <Input
                    type="date"
                    value={result.date}
                    onChange={(e) => {
                      const newResults = [...formData.lab_results];
                      newResults[index].date = e.target.value;
                      updateFormData('lab_results', newResults);
                    }}
                    className="w-36"
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    onClick={() => removeItem('lab_results', index)}
                  >
                    <Trash2 className="h-4 w-4 text-red-500" />
                  </Button>
                </div>
              ))}
              <Button
                type="button"
                variant="outline"
                onClick={() => addItem('lab_results', { test_name: '', value: '', unit: '', reference_range: '', date: '' })}
              >
                <Plus className="h-4 w-4 mr-2" />
                Agregar an├ílisis
              </Button>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => navigate(`/patients/${patientId}`)}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Anamnesis Nutricional</h1>
          <p className="text-gray-500 mt-1">Completa la informaci├│n paso a paso</p>
        </div>
      </div>

      {/* Progress */}
      <div className="flex items-center gap-2 overflow-x-auto pb-2">
        {steps.map((step, index) => (
          <div
            key={step.id}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg whitespace-nowrap ${
              index === currentStep
                ? 'bg-black text-white'
                : index < currentStep
                ? 'bg-gray-200 text-gray-700'
                : 'bg-gray-100 text-gray-400'
            }`}
          >
            {index < currentStep ? (
              <Check className="h-4 w-4" />
            ) : (
              <span className="text-sm font-medium">{index + 1}</span>
            )}
            <span className="text-sm hidden sm:inline">{step.title}</span>
          </div>
        ))}
      </div>

      {/* Content */}
      <Card>
        <CardHeader>
          <CardTitle className="text-xl">{steps[currentStep].title}</CardTitle>
          <p className="text-gray-500">{steps[currentStep].description}</p>
        </CardHeader>
        <CardContent>
          {renderStepContent()}
        </CardContent>
      </Card>

      {/* Navigation */}
      <div className="flex justify-between">
        <Button
          variant="outline"
          onClick={handlePrevious}
          disabled={currentStep === 0}
        >
          <ArrowLeft className="h-4 w-4 mr-2" />
          Anterior
        </Button>

        {currentStep === steps.length - 1 ? (
          <Button
            onClick={handleSubmit}
            disabled={saving}
            className="bg-black hover:bg-gray-800"
          >
            {saving ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : (
              <Check className="h-4 w-4 mr-2" />
            )}
            Guardar Anamnesis
          </Button>
        ) : (
          <Button
            onClick={handleNext}
            className="bg-black hover:bg-gray-800"
          >
            Siguiente
            <ArrowRight className="h-4 w-4 ml-2" />
          </Button>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuthStore } from '@/stores/authStore';
import { usePatientStore } from '@/stores/patientStore';
import { useFollowUpStore } from '@/stores/followUpStore';
import { useMealPlanStore } from '@/stores/mealPlanStore';
import { supabase } from '@/lib/supabase/client';
import type { Appointment } from '@/types';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { 
  Users, 
  Calendar, 
  TrendingUp, 
  Plus, 
  ChevronRight,
  Utensils,
  Activity,
  CalendarCheck,
  Check,
  X
} from 'lucide-react';
import { format, addDays, isBefore } from 'date-fns';
import { es } from 'date-fns/locale';
import { toast } from 'sonner';

export function Dashboard() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { patients, fetchPatients } = usePatientStore();
  const { followUpsWithPatient, fetchFollowUps } = useFollowUpStore();
  const { mealPlans, fetchMealPlans } = useMealPlanStore();

  const [appointments, setAppointments] = useState<Appointment[]>([]);

  const fetchAppointments = async (userId: string) => {
    try {
      const { data, error } = await (supabase as any)
        .from('appointments')
        .select('*')
        .eq('nutritionist_id', userId)
        .order('date', { ascending: true })
        .order('start_time', { ascending: true });
        
      if (!error && data) {
        setAppointments(data as Appointment[]);
      }
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    if (user) {
      fetchPatients(user.id);
      fetchFollowUps(user.id);
      fetchMealPlans(user.id);
      fetchAppointments(user.id);
    }
  }, [user]);

  const respondToAppointment = async (id: string, status: 'confirmed' | 'cancelled') => {
    try {
      const { error } = await (supabase as any)
        .from('appointments')
        .update({ status })
        .eq('id', id);

      if (error) throw error;
      toast.success(status === 'confirmed' ? 'Turno confirmado' : 'Turno rechazado');
      if (user) fetchAppointments(user.id);
    } catch (err) {
      toast.error('Ocurri├│ un error al procesar el turno');
    }
  };

  const stats = [
    {
      title: 'Total Pacientes',
      value: patients.length,
      icon: Users,
      trend: `+${patients.filter(p => {
        const created = new Date(p.created_at);
        const thisMonth = new Date();
        return created.getMonth() === thisMonth.getMonth() && 
               created.getFullYear() === thisMonth.getFullYear();
      }).length} este mes`,
      onClick: () => navigate('/patients'),
    },
    {
      title: 'Planes Activos',
      value: mealPlans.filter(mp => mp.is_active).length,
      icon: Utensils,
      trend: 'Activos',
      onClick: () => navigate('/meal-plans'),
    },
    {
      title: 'Citas Pr├│ximas',
      value: [...followUpsWithPatient.filter(fu => fu.next_appointment), ...appointments.filter(a => a.status === 'confirmed')].filter(item => {
        let date;
        if ('next_appointment' in item) {
          date = new Date(item.next_appointment!);
        } else {
          date = new Date(`${item.date}T${item.start_time}`);
        }
        const today = new Date();
        const nextWeek = addDays(today, 7);
        return isBefore(date, nextWeek) && isBefore(today, date);
      }).length,
      icon: Calendar,
      trend: 'Esta semana',
      onClick: () => navigate('/follow-ups'),
    },
    {
      title: 'Seguimientos',
      value: followUpsWithPatient.length,
      icon: TrendingUp,
      trend: 'Total',
      onClick: () => navigate('/follow-ups'),
    },
  ];

  const recentPatients = patients.slice(0, 5);
  
  const allUpcomingAppointments = [
    ...followUpsWithPatient
      .filter(fu => fu.next_appointment && new Date(fu.next_appointment) >= new Date(new Date().setHours(0,0,0,0)))
      .map(fu => ({
        id: fu.id,
        type: 'follow_up',
        date: new Date(fu.next_appointment!),
        patientName: fu.patient ? `${fu.patient.first_name} ${fu.patient.last_name}` : 'Paciente',
        patientId: fu.patient_id,
        subtitle: 'Control Autom├ítico'
      })),
    ...appointments
      .filter(a => a.status === 'confirmed' && new Date(`${a.date}T${a.start_time}`) >= new Date(new Date().setHours(0,0,0,0)))
      .map(a => ({
        id: a.id,
        type: 'booking',
        date: new Date(`${a.date}T${a.start_time}`),
        patientName: a.guest_name || 'Paciente Nuevo',
        patientId: null,
        subtitle: `${a.service_name} ÔÇó ${a.start_time.substring(0, 5)}`
      }))
  ].sort((a, b) => a.date.getTime() - b.date.getTime());

  const upcomingAppointments = allUpcomingAppointments.slice(0, 5);

  const getInitials = (firstName: string, lastName: string) => {
    return `${firstName[0]}${lastName[0]}`.toUpperCase();
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-700">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6 pb-2 border-b border-zinc-100">
        <div className="space-y-1.5">
          <h1 className="text-4xl font-extrabold tracking-tight text-zinc-900">Bienvenido, {user?.full_name?.split(' ')[0]}</h1>
          <p className="text-zinc-500 text-lg font-medium">Este es el resumen de tu consultorio al d├¡a de hoy.</p>
        </div>
        <Button onClick={() => navigate('/patients/new')} className="bg-emerald-600 hover:bg-emerald-700 hover:-translate-y-0.5 hover:shadow-lg text-white shadow-md transition-all duration-300 px-6 h-12 rounded-xl text-base">
          <Plus className="h-5 w-5 mr-2" />
          A├▒adir Paciente
        </Button>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, index) => (
          <Card 
            key={index} 
            className="cursor-pointer border-zinc-100 rounded-2xl shadow-sm hover:shadow-[0_8px_30px_rgb(0,0,0,0.06)] hover:-translate-y-1 transition-all duration-300"
            onClick={stat.onClick}
          >
            <CardHeader className="flex flex-row items-center justify-between pb-3">
              <CardTitle className="text-sm font-semibold text-zinc-500 tracking-wide">
                {stat.title}
              </CardTitle>
              <div className="h-12 w-12 bg-emerald-50 flex items-center justify-center rounded-2xl">
                <stat.icon className="h-6 w-6 text-emerald-600" />
              </div>
            </CardHeader>
            <CardContent>
              <div className="text-4xl font-black text-zinc-900 tracking-tighter">{stat.value}</div>
              <p className="text-xs font-bold text-zinc-400 mt-2 uppercase tracking-widest">{stat.trend}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Recent Patients */}
        <Card className="border-zinc-100 rounded-2xl shadow-sm hover:shadow-md transition-all">
          <CardHeader className="flex flex-row items-center justify-between border-b border-zinc-50 pb-5">
            <CardTitle className="text-xl font-extrabold tracking-tight text-zinc-900">Pacientes Recientes</CardTitle>
            <Button variant="ghost" size="sm" onClick={() => navigate('/patients')} className="text-emerald-700 font-semibold hover:text-emerald-800 hover:bg-emerald-50 rounded-xl">
              Ver todos
              <ChevronRight className="h-4 w-4 ml-1" />
            </Button>
          </CardHeader>
          <CardContent className="pt-5">
            {recentPatients.length === 0 ? (
              <div className="text-center py-8 text-gray-500">
                <Users className="h-12 w-12 mx-auto mb-3 text-gray-300" />
                <p>No hay pacientes registrados</p>
                <Button 
                  variant="outline" 
                  className="mt-4"
                  onClick={() => navigate('/patients/new')}
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Agregar paciente
                </Button>
              </div>
            ) : (
              <div className="space-y-4">
                {recentPatients.map((patient) => (
                  <div 
                    key={patient.id}
                    className="flex items-center justify-between p-3.5 rounded-xl hover:bg-zinc-50 hover:-translate-y-0.5 cursor-pointer transition-all duration-200"
                    onClick={() => navigate(`/patients/${patient.id}`)}
                  >
                    <div className="flex items-center gap-4">
                      <Avatar className="h-11 w-11 shadow-sm border border-zinc-100">
                        <AvatarFallback className="bg-gradient-to-br from-emerald-100 to-emerald-50 text-emerald-800 font-bold text-sm">
                          {getInitials(patient.first_name, patient.last_name)}
                        </AvatarFallback>
                      </Avatar>
                      <div className="space-y-0.5">
                        <p className="font-bold text-zinc-900">
                          {patient.first_name} {patient.last_name}
                        </p>
                        <p className="text-sm font-medium text-zinc-500">
                          {patient.age} a├▒os ÔÇó {patient.gender === 'male' ? 'Masculino' : patient.gender === 'female' ? 'Femenino' : 'Otro'}
                        </p>
                      </div>
                    </div>
                    <ChevronRight className="h-5 w-5 text-zinc-300" />
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Upcoming Follow Ups */}
        <Card className="border-zinc-100 rounded-2xl shadow-sm hover:shadow-md transition-all block lg:min-h-[400px]">
          <CardHeader className="flex flex-row items-center justify-between border-b border-zinc-50 pb-5">
            <CardTitle className="text-xl font-extrabold tracking-tight text-zinc-900">Controles Agendados</CardTitle>
            <Button variant="ghost" size="sm" onClick={() => navigate('/follow-ups')} className="text-emerald-700 font-semibold hover:text-emerald-800 hover:bg-emerald-50 rounded-xl">
              Ver calendario
              <ChevronRight className="h-4 w-4 ml-1" />
            </Button>
          </CardHeader>
          <CardContent className="pt-5">
            {upcomingAppointments.length === 0 ? (
              <div className="text-center py-8 text-gray-500">
                <Calendar className="h-12 w-12 mx-auto mb-3 text-gray-300" />
                <p>No hay citas programadas</p>
              </div>
            ) : (
              <div className="space-y-4">
                {upcomingAppointments.map((appt) => (
                  <div 
                    key={appt.id}
                    className="flex items-center justify-between p-3.5 rounded-xl hover:bg-zinc-50 hover:-translate-y-0.5 cursor-pointer transition-all duration-200"
                  >
                    <div className="flex items-center gap-4">
                      <div className={`w-11 h-11 rounded-xl shadow-sm flex items-center justify-center ${appt.type === 'booking' ? 'bg-emerald-600' : 'bg-zinc-900'}`}>
                        {appt.type === 'booking' ? <CalendarCheck className="h-5 w-5 text-white" /> : <Activity className="h-5 w-5 text-white" />}
                      </div>
                      <div className="space-y-0.5">
                        <p className="font-bold text-zinc-900">
                          {appt.patientName}
                        </p>
                        <p className="text-sm font-medium text-emerald-700">
                          {format(appt.date, "d 'de' MMMM", { locale: es })} <span className="text-zinc-400 mx-1">ÔÇó</span> <span className="text-zinc-500">{appt.subtitle}</span>
                        </p>
                      </div>
                    </div>
                    {appt.patientId && (
                      <Button variant="ghost" size="icon" className="rounded-xl hover:bg-zinc-100" onClick={() => navigate(`/patients/${appt.patientId}`)}>
                        <ChevronRight className="h-5 w-5 text-zinc-400" />
                      </Button>
                    )}
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Public Turnera Appointments list */}
      <Card className="border-emerald-100 shadow-sm relative overflow-hidden">
        <div className="absolute top-0 left-0 w-1 h-full bg-emerald-500 rounded-l-xl"></div>
        <CardHeader className="flex flex-row items-center justify-between border-b pb-4">
          <div>
            <CardTitle className="flex items-center gap-2">
              <CalendarCheck className="h-5 w-5 text-emerald-600" />
              Reservas de la Turnera P├║blica
            </CardTitle>
            <CardDescription>Pacientes que reservaron mediante tu enlace: <span className="text-xs bg-gray-100 px-2 py-1 rounded select-all font-mono">nutrixa.com/book/{user?.slug || 'tu-enlace'}</span></CardDescription>
          </div>
          <Button variant="outline" size="sm" onClick={() => user && fetchAppointments(user.id)}>
            Actualizar
          </Button>
        </CardHeader>
        <CardContent className="pt-6">
          {appointments.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              <Calendar className="h-12 w-12 mx-auto mb-3 text-gray-300" />
              <p>A├║n no tienes nuevas reservas online</p>
            </div>
          ) : (
            <div className="space-y-4">
              {appointments.map((appt) => (
                <div key={appt.id} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 bg-white border border-gray-100 hover:shadow-md transition-shadow rounded-xl gap-4">
                  <div className="flex gap-4">
                    {/* Date Block */}
                    <div className="bg-gray-50 px-4 py-2 rounded-lg border text-center flex-shrink-0 min-w-[5rem]">
                      <span className="block text-xs uppercase font-bold text-gray-500">
                        {format(new Date(appt.date), 'MMM', { locale: es })}
                      </span>
                      <span className="block text-2xl font-black text-gray-900">
                        {format(new Date(appt.date), 'd')}
                      </span>
                      <span className="block text-xs text-emerald-600 font-medium">{appt.start_time}</span>
                    </div>

                    {/* Details Block */}
                    <div className="flex flex-col justify-center">
                      <p className="font-bold text-gray-900 text-lg">{appt.guest_name}</p>
                      <p className="text-sm text-gray-600 flex items-center gap-1">
                        <Activity className="h-3 w-3" />
                        {appt.service_name} ÔÇö {appt.service_duration} min
                      </p>
                      <div className="flex items-center gap-3 mt-1 text-xs text-gray-500">
                        <span>{appt.guest_phone}</span>
                        <span className="w-1 h-1 bg-gray-300 rounded-full"></span>
                        <span className="font-medium text-green-700">${appt.service_price.toLocaleString('es-AR')}</span>
                      </div>
                    </div>
                  </div>

                  {/* Actions Block */}
                  <div className="flex items-center gap-2">
                     {appt.status === 'pending' && (
                      <>
                        <Button 
                          variant="default" 
                          className="bg-green-600 hover:bg-green-700 text-white" 
                          size="sm"
                          onClick={() => respondToAppointment(appt.id, 'confirmed')}
                        >
                          <Check className="h-4 w-4 mr-1"/> Confirmar
                        </Button>
                        <Button 
                          variant="outline" 
                          className="hover:bg-red-50 hover:text-red-600"
                          size="sm"
                          onClick={() => respondToAppointment(appt.id, 'cancelled')}
                        >
                          <X className="h-4 w-4"/>
                        </Button>
                      </>
                    )}
                    
                    {appt.status === 'confirmed' && (
                      <div className="px-3 py-1.5 bg-green-50 text-green-700 border border-green-200 font-semibold text-sm rounded-full flex items-center gap-1 shadow-sm">
                        <Check className="h-4 w-4" /> Confirmado
                      </div>
                    )}

                    {appt.status === 'cancelled' && (
                      <div className="px-3 py-1.5 bg-red-50 text-red-700 border border-red-200 font-semibold text-sm rounded-full flex items-center gap-1 shadow-sm">
                        <X className="h-4 w-4" /> Cancelado
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Quick Actions */}
      <Card className="border-gray-100 shadow-sm">
        <CardHeader className="border-b border-gray-50 pb-4">
          <CardTitle className="text-lg font-bold text-gray-900">Acceso R├ípido</CardTitle>
        </CardHeader>
        <CardContent className="pt-6">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            <Button 
              variant="outline" 
              className="h-28 flex flex-col items-center justify-center gap-3 border-gray-200 hover:bg-emerald-50 hover:text-emerald-700 hover:border-emerald-200 transition-all rounded-xl shadow-sm"
              onClick={() => navigate('/patients/new')}
            >
              <div className="p-2 bg-white rounded-lg shadow-sm">
                <Users className="h-5 w-5" />
              </div>
              <span className="font-semibold text-sm">Nuevo<br/>Paciente</span>
            </Button>
            
            <Button 
              variant="outline" 
              className="h-28 flex flex-col items-center justify-center gap-3 border-gray-200 hover:bg-emerald-50 hover:text-emerald-700 hover:border-emerald-200 transition-all rounded-xl shadow-sm"
              onClick={() => navigate('/recipes')}
            >
              <div className="p-2 bg-white rounded-lg shadow-sm">
                <Utensils className="h-5 w-5" />
              </div>
              <span className="font-semibold text-sm">Crear<br/>Receta</span>
            </Button>

            <Button 
              variant="outline" 
              className="h-28 flex flex-col items-center justify-center gap-3 border-gray-200 hover:bg-emerald-50 hover:text-emerald-700 hover:border-emerald-200 transition-all rounded-xl shadow-sm"
              onClick={() => navigate('/meal-plans')}
            >
              <div className="p-2 bg-white rounded-lg shadow-sm">
                <Activity className="h-5 w-5" />
              </div>
              <span className="font-semibold text-sm">Armar<br/>Plan</span>
            </Button>

            <Button 
              variant="outline" 
              className="h-28 flex flex-col items-center justify-center gap-3 border-gray-200 hover:bg-emerald-50 hover:text-emerald-700 hover:border-emerald-200 transition-all rounded-xl shadow-sm"
              onClick={() => navigate('/follow-ups')}
            >
              <div className="p-2 bg-white rounded-lg shadow-sm">
                <Calendar className="h-5 w-5" />
              </div>
              <span className="font-semibold text-sm">Registrar<br/>Control</span>
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAuthStore } from '@/stores/authStore';
import { useFollowUpStore } from '@/stores/followUpStore';
import { usePatientStore } from '@/stores/patientStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { ArrowLeft, Loader2, Plus, Save, Trash2, X } from 'lucide-react';

interface FollowUpFormData {
  patient_id: string;
  date: string;
  weight: string;
  notes: string;
  adherence: string;
  symptoms: string[];
  concerns: string[];
  next_appointment: string;
}

const initialFormData: FollowUpFormData = {
  patient_id: '',
  date: new Date().toISOString().split('T')[0],
  weight: '',
  notes: '',
  adherence: '',
  symptoms: [],
  concerns: [],
  next_appointment: '',
};

export function FollowUpForm() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const { user } = useAuthStore();
  const { selectedFollowUp, createFollowUp, updateFollowUp, getFollowUpById, loading } = useFollowUpStore();
  const { patients, fetchPatients } = usePatientStore();
  
  const isEditing = Boolean(id);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState<FollowUpFormData>(initialFormData);
  const [newSymptom, setNewSymptom] = useState('');
  const [newConcern, setNewConcern] = useState('');

  useEffect(() => {
    if (user) {
      fetchPatients(user.id);
    }
  }, [user]);

  useEffect(() => {
    if (isEditing && id) {
      getFollowUpById(id);
    }
  }, [id, isEditing]);

  useEffect(() => {
    if (isEditing && selectedFollowUp) {
      setFormData({
        patient_id: selectedFollowUp.patient_id,
        date: selectedFollowUp.date,
        weight: selectedFollowUp.weight.toString(),
        notes: selectedFollowUp.notes || '',
        adherence: selectedFollowUp.adherence || '',
        symptoms: selectedFollowUp.symptoms || [],
        concerns: selectedFollowUp.concerns || [],
        next_appointment: selectedFollowUp.next_appointment || '',
      });
    }
  }, [selectedFollowUp, isEditing]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user || !formData.patient_id) return;

    setSaving(true);
    
    try {
      const dataToSave = {
        date: formData.date,
        weight: parseFloat(formData.weight),
        notes: formData.notes || undefined,
        adherence: ((formData.adherence as string) === 'unspecified' || !formData.adherence) ? undefined : formData.adherence as 'excellent' | 'good' | 'fair' | 'poor',
        symptoms: formData.symptoms,
        concerns: formData.concerns,
        next_appointment: formData.next_appointment || undefined,
      };

      if (isEditing && id) {
        await updateFollowUp(id, dataToSave);
      } else {
        await createFollowUp(user.id, formData.patient_id, dataToSave);
      }
      navigate('/follow-ups');
    } catch (error) {
      console.error('Error saving follow up:', error);
    } finally {
      setSaving(false);
    }
  };

  const addSymptom = () => {
    if (newSymptom.trim()) {
      setFormData(prev => ({
        ...prev,
        symptoms: [...prev.symptoms, newSymptom.trim()],
      }));
      setNewSymptom('');
    }
  };

  const removeSymptom = (index: number) => {
    setFormData(prev => ({
      ...prev,
      symptoms: prev.symptoms.filter((_, i) => i !== index),
    }));
  };

  const addConcern = () => {
    if (newConcern.trim()) {
      setFormData(prev => ({
        ...prev,
        concerns: [...prev.concerns, newConcern.trim()],
      }));
      setNewConcern('');
    }
  };

  const removeConcern = (index: number) => {
    setFormData(prev => ({
      ...prev,
      concerns: prev.concerns.filter((_, i) => i !== index),
    }));
  };

  if (isEditing && loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => navigate('/follow-ups')}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-3xl font-bold text-gray-900">
            {isEditing ? 'Editar Control' : 'Nuevo Control'}
          </h1>
          <p className="text-gray-500 mt-1">
            {isEditing 
              ? 'Actualiza el registro de seguimiento' 
              : 'Registra el progreso de tu paciente'}
          </p>
        </div>
      </div>

      <form onSubmit={handleSubmit}>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Basic Info */}
          <Card>
            <CardHeader>
              <CardTitle className="text-lg font-semibold">Informaci├│n del Control</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {!isEditing && (
                <div className="space-y-2">
                  <Label htmlFor="patient">Paciente *</Label>
                  <Select
                    value={formData.patient_id}
                    onValueChange={(value) => setFormData(prev => ({ ...prev, patient_id: value }))}
                    required
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Seleccionar paciente..." />
                    </SelectTrigger>
                    <SelectContent>
                      {patients.map((patient) => (
                        <SelectItem key={patient.id} value={patient.id}>
                          {patient.first_name} {patient.last_name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="date">Fecha *</Label>
                  <Input
                    id="date"
                    type="date"
                    value={formData.date}
                    onChange={(e) => setFormData(prev => ({ ...prev, date: e.target.value }))}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="weight">Peso (kg) *</Label>
                  <Input
                    id="weight"
                    type="number"
                    step="0.1"
                    value={formData.weight}
                    onChange={(e) => setFormData(prev => ({ ...prev, weight: e.target.value }))}
                    required
                    placeholder="70.5"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="adherence">Adherencia al plan</Label>
                <Select
                  value={formData.adherence}
                  onValueChange={(value) => setFormData(prev => ({ ...prev, adherence: value }))}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Seleccionar..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="unspecified">No especificado</SelectItem>
                    <SelectItem value="excellent">Excelente</SelectItem>
                    <SelectItem value="good">Buena</SelectItem>
                    <SelectItem value="fair">Regular</SelectItem>
                    <SelectItem value="poor">Deficiente</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="next_appointment">Pr├│xima cita</Label>
                <Input
                  id="next_appointment"
                  type="date"
                  value={formData.next_appointment}
                  onChange={(e) => setFormData(prev => ({ ...prev, next_appointment: e.target.value }))}
                />
              </div>
            </CardContent>
          </Card>

          {/* Symptoms and Concerns */}
          <Card>
            <CardHeader>
              <CardTitle className="text-lg font-semibold">S├¡ntomas e Inquietudes</CardTitle>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Symptoms */}
              <div className="space-y-2">
                <Label>S├¡ntomas</Label>
                <div className="flex gap-2">
                  <Input
                    placeholder="Agregar s├¡ntoma..."
                    value={newSymptom}
                    onChange={(e) => setNewSymptom(e.target.value)}
                    onKeyPress={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        addSymptom();
                      }
                    }}
                  />
                  <Button type="button" variant="outline" onClick={addSymptom}>
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>
                <div className="flex flex-wrap gap-2 mt-2">
                  {formData.symptoms.map((symptom, index) => (
                    <div key={index} className="flex items-center gap-1 bg-red-50 text-red-700 rounded-full px-3 py-1">
                      <span className="text-sm">{symptom}</span>
                      <button
                        type="button"
                        onClick={() => removeSymptom(index)}
                        className="hover:text-red-900"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>

              {/* Concerns */}
              <div className="space-y-2">
                <Label>Inquietudes</Label>
                <div className="flex gap-2">
                  <Input
                    placeholder="Agregar inquietud..."
                    value={newConcern}
                    onChange={(e) => setNewConcern(e.target.value)}
                    onKeyPress={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        addConcern();
                      }
                    }}
                  />
                  <Button type="button" variant="outline" onClick={addConcern}>
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>
                <div className="flex flex-wrap gap-2 mt-2">
                  {formData.concerns.map((concern, index) => (
                    <div key={index} className="flex items-center gap-1 bg-yellow-50 text-yellow-700 rounded-full px-3 py-1">
                      <span className="text-sm">{concern}</span>
                      <button
                        type="button"
                        onClick={() => removeConcern(index)}
                        className="hover:text-yellow-900"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Notes */}
          <Card className="lg:col-span-2">
            <CardHeader>
              <CardTitle className="text-lg font-semibold">Notas</CardTitle>
            </CardHeader>
            <CardContent>
              <Textarea
                value={formData.notes}
                onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
                placeholder="Observaciones adicionales sobre el paciente..."
                rows={5}
              />
            </CardContent>
          </Card>
        </div>

        {/* Actions */}
        <div className="flex justify-end gap-4 mt-6">
          <Button
            type="button"
            variant="outline"
            onClick={() => navigate('/follow-ups')}
          >
            Cancelar
          </Button>
          <Button
            type="submit"
            className="bg-black hover:bg-gray-800"
            disabled={saving || (!isEditing && !formData.patient_id) || !formData.weight}
          >
            {saving ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : (
              <Save className="h-4 w-4 mr-2" />
            )}
            {isEditing ? 'Guardar cambios' : 'Registrar control'}
          </Button>
        </div>
      </form>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuthStore } from '@/stores/authStore';
import { useFollowUpStore } from '@/stores/followUpStore';
import { usePatientStore } from '@/stores/patientStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { 
  Plus, 
  MoreVertical, 
  Edit, 
  Trash2, 
  Calendar,
  TrendingUp,
  Weight,
  ChevronRight,
  Loader2,
  Download
} from 'lucide-react';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import type { FollowUp } from '@/types';
import { exportFollowUpToPDF } from '@/utils/pdfExport';

const adherenceLabels = {
  excellent: { label: 'Excelente', color: 'bg-green-100 text-green-800' },
  good: { label: 'Buena', color: 'bg-blue-100 text-blue-800' },
  fair: { label: 'Regular', color: 'bg-yellow-100 text-yellow-800' },
  poor: { label: 'Deficiente', color: 'bg-red-100 text-red-800' },
};

export function FollowUps() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { followUpsWithPatient, loading, fetchFollowUps, deleteFollowUp } = useFollowUpStore();
  const { patients } = usePatientStore();
  
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [followUpToDelete, setFollowUpToDelete] = useState<FollowUp | null>(null);

  useEffect(() => {
    if (user) {
      fetchFollowUps(user.id);
    }
  }, [user]);

  const handleDelete = async () => {
    if (followUpToDelete) {
      await deleteFollowUp(followUpToDelete.id);
      setDeleteDialogOpen(false);
      setFollowUpToDelete(null);
    }
  };

  const getPatientName = (patientId: string) => {
    const patient = patients.find(p => p.id === patientId);
    return patient ? `${patient.first_name} ${patient.last_name}` : 'Paciente no encontrado';
  };

  const getInitials = (patientId: string) => {
    const patient = patients.find(p => p.id === patientId);
    if (!patient) return '?';
    return `${patient.first_name[0]}${patient.last_name[0]}`.toUpperCase();
  };

  const handleExport = (followUp: FollowUp) => {
    const patient = patients.find(p => p.id === followUp.patient_id);
    if (patient) {
      const patientFollowUps = followUpsWithPatient
        .filter(fu => fu.patient_id === patient.id)
        .map(fu => fu as FollowUp);
      exportFollowUpToPDF(patient, patientFollowUps);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Seguimiento</h1>
          <p className="text-gray-500 mt-1">Registra y visualiza el progreso de tus pacientes</p>
        </div>
        <Button onClick={() => navigate('/follow-ups/new')} className="bg-black hover:bg-gray-800">
          <Plus className="h-4 w-4 mr-2" />
          Nuevo Control
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-black flex items-center justify-center">
                <TrendingUp className="h-5 w-5 text-white" />
              </div>
              <div>
                <p className="text-sm text-gray-500">Total controles</p>
                <p className="text-2xl font-bold">{followUpsWithPatient.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-green-100 flex items-center justify-center">
                <Calendar className="h-5 w-5 text-green-600" />
              </div>
              <div>
                <p className="text-sm text-gray-500">Citas esta semana</p>
                <p className="text-2xl font-bold">
                  {followUpsWithPatient.filter(fu => {
                    if (!fu.next_appointment) return false;
                    const nextDate = new Date(fu.next_appointment);
                    const today = new Date();
                    const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
                    return nextDate >= today && nextDate <= nextWeek;
                  }).length}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-blue-100 flex items-center justify-center">
                <Weight className="h-5 w-5 text-blue-600" />
              </div>
              <div>
                <p className="text-sm text-gray-500">Pacientes con seguimiento</p>
                <p className="text-2xl font-bold">
                  {new Set(followUpsWithPatient.map(fu => fu.patient_id)).size}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Follow Ups List */}
      {loading ? (
        <div className="flex justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
        </div>
      ) : followUpsWithPatient.length === 0 ? (
        <Card>
          <CardContent className="text-center py-12">
            <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <TrendingUp className="h-8 w-8 text-gray-400" />
            </div>
            <h3 className="text-lg font-medium text-gray-900 mb-1">No hay controles registrados</h3>
            <p className="text-gray-500 mb-4">Comienza registrando el primer seguimiento</p>
            <Button onClick={() => navigate('/follow-ups/new')} className="bg-black hover:bg-gray-800">
              <Plus className="h-4 w-4 mr-2" />
              Nuevo Control
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {followUpsWithPatient.map((followUp) => (
            <Card key={followUp.id} className="group hover:shadow-md transition-shadow">
              <CardContent className="p-6">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-4">
                    <Avatar className="h-12 w-12">
                      <AvatarFallback className="bg-gray-200 text-gray-700">
                        {getInitials(followUp.patient_id)}
                      </AvatarFallback>
                    </Avatar>
                    <div>
                      <p className="font-semibold text-gray-900">
                        {getPatientName(followUp.patient_id)}
                      </p>
                      <p className="text-sm text-gray-500">
                        {format(new Date(followUp.date), "d 'de' MMMM, yyyy", { locale: es })}
                      </p>
                      <div className="flex items-center gap-3 mt-1">
                        <span className="text-lg font-bold">{followUp.weight} kg</span>
                        {followUp.adherence && (
                          <Badge 
                            variant="secondary" 
                            className={adherenceLabels[followUp.adherence].color}
                          >
                            {adherenceLabels[followUp.adherence].label}
                          </Badge>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {followUp.next_appointment && (
                      <div className="text-right mr-4 hidden sm:block">
                        <p className="text-sm text-gray-500">Pr├│xima cita</p>
                        <p className="font-medium">
                          {format(new Date(followUp.next_appointment), "d MMM", { locale: es })}
                        </p>
                      </div>
                    )}

                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon">
                          <MoreVertical className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => navigate(`/follow-ups/${followUp.id}/edit`)}>
                          <Edit className="h-4 w-4 mr-2" />
                          Editar
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => handleExport(followUp)}>
                          <Download className="h-4 w-4 mr-2" />
                          Exportar PDF
                        </DropdownMenuItem>
                        <DropdownMenuItem 
                          className="text-red-600"
                          onClick={() => {
                            setFollowUpToDelete(followUp);
                            setDeleteDialogOpen(true);
                          }}
                        >
                          <Trash2 className="h-4 w-4 mr-2" />
                          Eliminar
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                </div>

                {(followUp.symptoms?.length > 0 || followUp.concerns?.length > 0 || followUp.notes) && (
                  <div className="mt-4 pt-4 border-t">
                    {followUp.symptoms?.length > 0 && (
                      <div className="mb-2">
                        <span className="text-sm text-gray-500">S├¡ntomas: </span>
                        <span className="text-sm">{followUp.symptoms.join(', ')}</span>
                      </div>
                    )}
                    {followUp.concerns?.length > 0 && (
                      <div className="mb-2">
                        <span className="text-sm text-gray-500">Inquietudes: </span>
                        <span className="text-sm">{followUp.concerns.join(', ')}</span>
                      </div>
                    )}
                    {followUp.notes && (
                      <div>
                        <span className="text-sm text-gray-500">Notas: </span>
                        <span className="text-sm">{followUp.notes}</span>
                      </div>
                    )}
                  </div>
                )}
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>┬┐Eliminar control?</AlertDialogTitle>
            <AlertDialogDescription>
              Esta acci├│n eliminar├í el registro de seguimiento. Esta acci├│n no se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-red-600 hover:bg-red-700">
              Eliminar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

