import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useAuthStore } from '@/stores/authStore';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Loader2, Eye, EyeOff, Activity, Users, CalendarDays } from 'lucide-react';

export function Login() {
  const navigate = useNavigate();
  const { signIn, signUp, loading, user } = useAuthStore();
  
  const [searchParams] = useSearchParams();
  
  useEffect(() => {
    if (user) {
      navigate('/dashboard');
    }
  }, [user, navigate]);

  useEffect(() => {
    if (searchParams.get('signup') === 'true') {
      setIsSignUp(true);
    }
  }, [searchParams]);
  
  const [isSignUp, setIsSignUp] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    fullName: '',
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (isSignUp) {
      const { error } = await signUp(formData.email, formData.password, formData.fullName);
      if (error) {
        setError(error);
      } else {
        setError('Cuenta creada. Redirigiendo al dashboard...');
      }
    } else {
      const { error } = await signIn(formData.email, formData.password);
      if (error) {
        setError(error);
      } else {
        navigate('/dashboard');
      }
    }
  };

  return (
    <div className="min-h-screen grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 bg-white">
      
      {/* Left Panel - Branding (Hidden on mobile) */}
      <div className="hidden md:flex flex-col justify-between bg-zinc-900 border-r border-zinc-800 lg:col-span-3 relative overflow-hidden">
        {/* Abstract beautiful Background Image */}
        <img 
          src="https://images.unsplash.com/photo-1490645935967-10de6ba17061?auto=format&fit=crop&q=80&w=2653" 
          alt="Nutrition Background" 
          className="absolute inset-0 w-full h-full object-cover opacity-30 mix-blend-overlay"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-black/80" />
        
        {/* Top left mini text */}
        <div className="relative z-10 p-10 lg:p-14">
          <div className="flex items-center gap-2 text-white/80 font-medium tracking-widest text-sm uppercase">
            <Activity className="h-4 w-4" />
            <span>Sistema Profesional de Salud</span>
          </div>
        </div>
        
        {/* Value Proposition */}
        <div className="relative z-10 p-10 lg:p-14 text-white space-y-8 max-w-2xl animate-in fade-in slide-in-from-bottom-8 duration-1000 fill-mode-both delay-300">
          <h1 className="text-4xl lg:text-6xl font-extrabold tracking-tight text-white mb-4 leading-tight">
            Lleva tu consulta nutricional al siguiente nivel.
          </h1>
          <p className="text-lg text-zinc-300 leading-relaxed font-light">
            Una soluci├│n integral para profesionales: gestiona pacientes, dise├▒a planes personalizados, controla tus ingresos y automatiza tu agenda, todo desde un ├║nico lugar.
          </p>
          
          {/* Features Grid */}
          <div className="grid grid-cols-2 gap-6 pt-8 border-t border-white/10">
            <div className="flex items-center gap-3">
              <div className="h-10 w-10 flex items-center justify-center rounded-lg bg-emerald-500/20 text-emerald-400">
                <Users className="h-5 w-5" />
              </div>
              <p className="text-sm font-medium text-zinc-300">Pacientes</p>
            </div>
            <div className="flex items-center gap-3">
              <div className="h-10 w-10 flex items-center justify-center rounded-lg bg-emerald-500/20 text-emerald-400">
                <CalendarDays className="h-5 w-5" />
              </div>
              <p className="text-sm font-medium text-zinc-300">Turnera P├║blica</p>
            </div>
          </div>
        </div>
      </div>

      {/* Right Panel - Auth Form */}
      <div className="flex flex-col justify-center min-h-screen px-4 py-12 sm:px-6 lg:px-8 bg-zinc-50 lg:col-span-2 relative">
        <div className="mx-auto w-full max-w-sm animate-in fade-in zoom-in-95 duration-700 fill-mode-both">
          
          {/* Logo */}
          <div className="flex justify-center mb-10 animate-in slide-in-from-top-4 duration-500 delay-150 fill-mode-both">
            <img 
              src="/logoNutrixa.png" 
              alt="Nutrixa" 
              className="h-20 w-auto object-contain drop-shadow-sm transition-transform duration-500 hover:scale-105" 
            />
          </div>

          <div className="text-center mb-8 animate-in slide-in-from-bottom-4 duration-500 delay-200 fill-mode-both">
            <h2 className="text-3xl font-bold tracking-tight text-gray-900 transition-all">
              {isSignUp ? 'Empieza hoy' : 'Bienvenido de nuevo'}
            </h2>
            <p className="mt-2 text-sm text-gray-600">
              {isSignUp 
                ? 'Ingresa tus datos para crear tu cuenta profesional' 
                : 'Usa tus credenciales para acceder a tu escritorio'}
            </p>
          </div>
          
          <form onSubmit={handleSubmit} className="space-y-5 animate-in slide-in-from-bottom-4 duration-500 delay-300 fill-mode-both">
            {error && (
              <Alert variant={error.includes('creada') ? 'default' : 'destructive'} className="bg-red-50 text-red-700 border-red-200 animate-in fade-in slide-in-from-top-2 duration-300">
                <AlertDescription>{error}</AlertDescription>
              </Alert>
            )}

            {isSignUp && (
              <div className="space-y-1 animate-in fade-in slide-in-from-top-2 duration-300">
                <Label htmlFor="fullName" className="text-sm font-medium text-gray-700">Nombre completo</Label>
                <Input
                  id="fullName"
                  type="text"
                  placeholder="Lic. Mar├¡a P├®rez"
                  value={formData.fullName}
                  onChange={(e) => setFormData({ ...formData, fullName: e.target.value })}
                  required
                  className="h-12 border-gray-300 focus:ring-emerald-600 focus:border-emerald-600 rounded-lg shadow-sm transition-all duration-200 hover:border-gray-400"
                />
              </div>
            )}

            <div className="space-y-1 transition-all duration-300">
              <Label htmlFor="email" className="text-sm font-medium text-gray-700">Correo electr├│nico</Label>
              <Input
                id="email"
                type="email"
                placeholder="tu@email.com"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                required
                className="h-12 border-gray-300 focus:ring-emerald-600 focus:border-emerald-600 rounded-lg shadow-sm transition-all duration-200 hover:border-gray-400"
              />
            </div>

            <div className="space-y-1 transition-all duration-300">
              <div className="flex items-center justify-between">
                <Label htmlFor="password" className="text-sm font-medium text-gray-700">Contrase├▒a</Label>
                {!isSignUp && (
                  <a href="#" className="text-xs font-medium text-emerald-700 hover:text-emerald-800 transition-colors">
                    ┬┐Olvidaste tu contrase├▒a?
                  </a>
                )}
              </div>
              <div className="relative">
                <Input
                  id="password"
                  type={showPassword ? 'text' : 'password'}
                  placeholder="ÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇó"
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  required
                  className="h-12 pr-10 border-gray-300 focus:ring-emerald-600 focus:border-emerald-600 rounded-lg shadow-sm transition-all duration-200 hover:border-gray-400"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-emerald-700 focus:outline-none transition-colors"
                >
                  {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                </button>
              </div>
            </div>

            <Button 
              type="submit" 
              className="w-full h-12 text-base font-semibold bg-emerald-600 hover:bg-emerald-700 hover:shadow-lg hover:-translate-y-0.5 text-white shadow-md rounded-lg transition-all duration-300 active:translate-y-0 active:shadow-md"
              disabled={loading}
            >
              <div className="relative flex items-center justify-center w-full">
                {loading ? (
                  <Loader2 className="h-5 w-5 animate-spin" />
                ) : (
                  <span className="transition-all duration-300">{isSignUp ? 'Crear cuenta gratuita' : 'Ingresar a mi cuenta'}</span>
                )}
              </div>
            </Button>
          </form>

          <div className="mt-8">
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-gray-300" />
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="px-2 bg-zinc-50 text-gray-500">O tambi├®n puedes</span>
              </div>
            </div>

            <div className="mt-6 text-center">
              <button
                type="button"
                onClick={() => {
                  setIsSignUp(!isSignUp);
                  setError(null);
                }}
                className="text-sm font-medium text-emerald-700 hover:text-emerald-800 transition-colors focus:outline-none"
              >
                {isSignUp 
                  ? '┬┐Ya tienes una cuenta? Inicia sesi├│n' 
                  : '┬┐No tienes cuenta? Registrate como Profesional'}
              </button>
            </div>
          </div>
          
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAuthStore } from '@/stores/authStore';
import { useMealPlanStore } from '@/stores/mealPlanStore';
import { usePatientStore } from '@/stores/patientStore';
import { useRecipeStore } from '@/stores/recipeStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { ArrowLeft, Loader2, Plus, Save, Trash2, ChevronDown, ChevronUp } from 'lucide-react';
import type { MealPlanFormData, MealFormData, MealType } from '@/types';

const daysOfWeek = [
  { value: 1, label: 'Lunes' },
  { value: 2, label: 'Martes' },
  { value: 3, label: 'Mi├®rcoles' },
  { value: 4, label: 'Jueves' },
  { value: 5, label: 'Viernes' },
  { value: 6, label: 'S├íbado' },
  { value: 7, label: 'Domingo' },
];

const mealTypes: { value: MealType; label: string; defaultTime: string }[] = [
  { value: 'breakfast', label: 'Desayuno', defaultTime: '08:00' },
  { value: 'mid_morning', label: 'Media Ma├▒ana', defaultTime: '10:30' },
  { value: 'lunch', label: 'Almuerzo', defaultTime: '13:00' },
  { value: 'snack', label: 'Merienda', defaultTime: '16:30' },
  { value: 'dinner', label: 'Cena', defaultTime: '20:00' },
];

const emptyMeal: MealFormData = {
  type: 'breakfast',
  name: '',
  time: '08:00',
  recipes: [],
  notes: '',
};

const initialFormData: MealPlanFormData = {
  name: '',
  description: '',
  start_date: '',
  end_date: '',
  daily_calories: '',
  macros: {
    protein: '30',
    carbs: '40',
    fats: '30',
  },
  days: daysOfWeek.map(day => ({
    day_of_week: day.value,
    meals: [],
  })),
};

export function MealPlanForm() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const { user } = useAuthStore();
  const { selectedMealPlan, createMealPlan, updateMealPlan, getMealPlanById, loading } = useMealPlanStore();
  const { patients, fetchPatients } = usePatientStore();
  const { recipes, fetchRecipes } = useRecipeStore();
  
  const isEditing = Boolean(id);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState<MealPlanFormData>(initialFormData);
  const [selectedPatient, setSelectedPatient] = useState('');
  const [expandedDays, setExpandedDays] = useState<number[]>([1]);

  useEffect(() => {
    if (user) {
      fetchPatients(user.id);
      fetchRecipes(user.id);
    }
  }, [user]);

  useEffect(() => {
    if (isEditing && id) {
      getMealPlanById(id);
    }
  }, [id, isEditing]);

  useEffect(() => {
    if (isEditing && selectedMealPlan) {
      setSelectedPatient(selectedMealPlan.patient_id);
      setFormData({
        name: selectedMealPlan.name,
        description: selectedMealPlan.description || '',
        start_date: selectedMealPlan.start_date,
        end_date: selectedMealPlan.end_date || '',
        daily_calories: selectedMealPlan.daily_calories.toString(),
        macros: {
          protein: selectedMealPlan.macros.protein.toString(),
          carbs: selectedMealPlan.macros.carbs.toString(),
          fats: selectedMealPlan.macros.fats.toString(),
        },
        days: selectedMealPlan.days.map(day => ({
          day_of_week: day.day_of_week,
          meals: day.meals.map(meal => ({
            type: meal.type,
            name: meal.name,
            time: meal.time,
            recipes: meal.recipes.map(r => ({
              recipe_id: r.recipe_id,
              quantity: r.quantity.toString(),
            })),
            notes: meal.notes || '',
          })),
        })),
      });
    }
  }, [selectedMealPlan, isEditing]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user || !selectedPatient) return;

    setSaving(true);
    
    try {
      if (isEditing && id) {
        await updateRecipe(id, formData);
      } else {
        await createMealPlan(user.id, selectedPatient, formData);
      }
      navigate('/meal-plans');
    } catch (error) {
      console.error('Error saving meal plan:', error);
    } finally {
      setSaving(false);
    }
  };

  const toggleDay = (dayValue: number) => {
    setExpandedDays(prev => 
      prev.includes(dayValue)
        ? prev.filter(d => d !== dayValue)
        : [...prev, dayValue]
    );
  };

  const addMeal = (dayIndex: number) => {
    setFormData(prev => {
      const newDays = [...prev.days];
      newDays[dayIndex] = {
        ...newDays[dayIndex],
        meals: [...newDays[dayIndex].meals, { ...emptyMeal, type: 'breakfast' }],
      };
      return { ...prev, days: newDays };
    });
  };

  const updateMeal = (dayIndex: number, mealIndex: number, field: keyof MealFormData, value: any) => {
    setFormData(prev => {
      const newDays = [...prev.days];
      const newMeals = [...newDays[dayIndex].meals];
      newMeals[mealIndex] = { ...newMeals[mealIndex], [field]: value };
      newDays[dayIndex] = { ...newDays[dayIndex], meals: newMeals };
      return { ...prev, days: newDays };
    });
  };

  const removeMeal = (dayIndex: number, mealIndex: number) => {
    setFormData(prev => {
      const newDays = [...prev.days];
      newDays[dayIndex] = {
        ...newDays[dayIndex],
        meals: newDays[dayIndex].meals.filter((_, i) => i !== mealIndex),
      };
      return { ...prev, days: newDays };
    });
  };

  const addRecipeToMeal = (dayIndex: number, mealIndex: number) => {
    setFormData(prev => {
      const newDays = [...prev.days];
      const newMeals = [...newDays[dayIndex].meals];
      newMeals[mealIndex] = {
        ...newMeals[mealIndex],
        recipes: [...newMeals[mealIndex].recipes, { recipe_id: '', quantity: '1' }],
      };
      newDays[dayIndex] = { ...newDays[dayIndex], meals: newMeals };
      return { ...prev, days: newDays };
    });
  };

  const updateRecipeInMeal = (dayIndex: number, mealIndex: number, recipeIndex: number, field: string, value: string) => {
    setFormData(prev => {
      const newDays = [...prev.days];
      const newMeals = [...newDays[dayIndex].meals];
      const newRecipes = [...newMeals[mealIndex].recipes];
      newRecipes[recipeIndex] = { ...newRecipes[recipeIndex], [field]: value };
      newMeals[mealIndex] = { ...newMeals[mealIndex], recipes: newRecipes };
      newDays[dayIndex] = { ...newDays[dayIndex], meals: newMeals };
      return { ...prev, days: newDays };
    });
  };

  const removeRecipeFromMeal = (dayIndex: number, mealIndex: number, recipeIndex: number) => {
    setFormData(prev => {
      const newDays = [...prev.days];
      const newMeals = [...newDays[dayIndex].meals];
      newMeals[mealIndex] = {
        ...newMeals[mealIndex],
        recipes: newMeals[mealIndex].recipes.filter((_, i) => i !== recipeIndex),
      };
      newDays[dayIndex] = { ...newDays[dayIndex], meals: newMeals };
      return { ...prev, days: newDays };
    });
  };

  if (isEditing && loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => navigate('/meal-plans')}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-3xl font-bold text-gray-900">
            {isEditing ? 'Editar Plan' : 'Nuevo Plan de Alimentaci├│n'}
          </h1>
          <p className="text-gray-500 mt-1">
            {isEditing 
              ? 'Actualiza el plan nutricional' 
              : 'Dise├▒a un plan personalizado para tu paciente'}
          </p>
        </div>
      </div>

      <form onSubmit={handleSubmit}>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Basic Info */}
            <Card>
              <CardHeader>
                <CardTitle className="text-lg font-semibold">Informaci├│n del Plan</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                {!isEditing && (
                  <div className="space-y-2">
                    <Label htmlFor="patient">Paciente *</Label>
                    <Select
                      value={selectedPatient}
                      onValueChange={setSelectedPatient}
                      required
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Seleccionar paciente..." />
                      </SelectTrigger>
                      <SelectContent>
                        {patients.map((patient) => (
                          <SelectItem key={patient.id} value={patient.id}>
                            {patient.first_name} {patient.last_name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                )}

                <div className="space-y-2">
                  <Label htmlFor="name">Nombre del plan *</Label>
                  <Input
                    id="name"
                    value={formData.name}
                    onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                    required
                    placeholder="Ej: Plan de adelgazamiento - Fase 1"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="description">Descripci├│n</Label>
                  <Textarea
                    id="description"
                    value={formData.description}
                    onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                    placeholder="Objetivos y caracter├¡sticas del plan..."
                    rows={3}
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="start_date">Fecha de inicio *</Label>
                    <Input
                      id="start_date"
                      type="date"
                      value={formData.start_date}
                      onChange={(e) => setFormData(prev => ({ ...prev, start_date: e.target.value }))}
                      required
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="end_date">Fecha de fin (opcional)</Label>
                    <Input
                      id="end_date"
                      type="date"
                      value={formData.end_date}
                      onChange={(e) => setFormData(prev => ({ ...prev, end_date: e.target.value }))}
                    />
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Weekly Plan */}
            <Card>
              <CardHeader>
                <CardTitle className="text-lg font-semibold">Plan Semanal</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {formData.days.map((day, dayIndex) => (
                    <div key={day.day_of_week} className="border rounded-lg overflow-hidden">
                      <button
                        type="button"
                        onClick={() => toggleDay(day.day_of_week)}
                        className="w-full flex items-center justify-between p-4 bg-gray-50 hover:bg-gray-100 transition-colors"
                      >
                        <span className="font-medium">{daysOfWeek[dayIndex].label}</span>
                        <div className="flex items-center gap-2">
                          <span className="text-sm text-gray-500">
                            {day.meals.length} comidas
                          </span>
                          {expandedDays.includes(day.day_of_week) ? (
                            <ChevronUp className="h-4 w-4" />
                          ) : (
                            <ChevronDown className="h-4 w-4" />
                          )}
                        </div>
                      </button>

                      {expandedDays.includes(day.day_of_week) && (
                        <div className="p-4 space-y-4">
                          {day.meals.length === 0 ? (
                            <p className="text-center text-gray-500 py-4">
                              No hay comidas asignadas para este d├¡a
                            </p>
                          ) : (
                            day.meals.map((meal, mealIndex) => (
                              <div key={mealIndex} className="p-4 bg-gray-50 rounded-lg space-y-3">
                                <div className="flex items-center justify-between">
                                  <div className="flex gap-2 flex-1">
                                    <Select
                                      value={meal.type}
                                      onValueChange={(value) => updateMeal(dayIndex, mealIndex, 'type', value as MealType)}
                                    >
                                      <SelectTrigger className="w-40">
                                        <SelectValue />
                                      </SelectTrigger>
                                      <SelectContent>
                                        {mealTypes.map((type) => (
                                          <SelectItem key={type.value} value={type.value}>
                                            {type.label}
                                          </SelectItem>
                                        ))}
                                      </SelectContent>
                                    </Select>
                                    <Input
                                      placeholder="Nombre (opcional)"
                                      value={meal.name}
                                      onChange={(e) => updateMeal(dayIndex, mealIndex, 'name', e.target.value)}
                                      className="flex-1"
                                    />
                                    <Input
                                      type="time"
                                      value={meal.time}
                                      onChange={(e) => updateMeal(dayIndex, mealIndex, 'time', e.target.value)}
                                      className="w-28"
                                    />
                                  </div>
                                  <Button
                                    type="button"
                                    variant="ghost"
                                    size="icon"
                                    onClick={() => removeMeal(dayIndex, mealIndex)}
                                    className="text-red-500"
                                  >
                                    <Trash2 className="h-4 w-4" />
                                  </Button>
                                </div>

                                {/* Recipes */}
                                <div className="space-y-2">
                                  {meal.recipes.map((recipe, recipeIndex) => (
                                    <div key={recipeIndex} className="flex gap-2">
                                      <Select
                                        value={recipe.recipe_id}
                                        onValueChange={(value) => updateRecipeInMeal(dayIndex, mealIndex, recipeIndex, 'recipe_id', value)}
                                      >
                                        <SelectTrigger className="flex-1">
                                          <SelectValue placeholder="Seleccionar receta..." />
                                        </SelectTrigger>
                                        <SelectContent>
                                          {recipes.map((r) => (
                                            <SelectItem key={r.id} value={r.id}>
                                              {r.name}
                                            </SelectItem>
                                          ))}
                                        </SelectContent>
                                      </Select>
                                      <Input
                                        type="number"
                                        step="0.1"
                                        placeholder="Cant."
                                        value={recipe.quantity}
                                        onChange={(e) => updateRecipeInMeal(dayIndex, mealIndex, recipeIndex, 'quantity', e.target.value)}
                                        className="w-24"
                                      />
                                      <Button
                                        type="button"
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => removeRecipeFromMeal(dayIndex, mealIndex, recipeIndex)}
                                        className="text-red-500"
                                      >
                                        <Trash2 className="h-4 w-4" />
                                      </Button>
                                    </div>
                                  ))}
                                  <Button
                                    type="button"
                                    variant="outline"
                                    size="sm"
                                    onClick={() => addRecipeToMeal(dayIndex, mealIndex)}
                                  >
                                    <Plus className="h-3 w-3 mr-1" />
                                    Agregar receta
                                  </Button>
                                </div>

                                <Textarea
                                  placeholder="Notas adicionales..."
                                  value={meal.notes}
                                  onChange={(e) => updateMeal(dayIndex, mealIndex, 'notes', e.target.value)}
                                  className="min-h-[60px]"
                                />
                              </div>
                            ))
                          )}
                          <Button
                            type="button"
                            variant="outline"
                            onClick={() => addMeal(dayIndex)}
                            className="w-full"
                          >
                            <Plus className="h-4 w-4 mr-2" />
                            Agregar comida
                          </Button>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Macros */}
            <Card>
              <CardHeader>
                <CardTitle className="text-lg font-semibold">Macronutrientes</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="daily_calories">Calor├¡as diarias</Label>
                  <Input
                    id="daily_calories"
                    type="number"
                    value={formData.daily_calories}
                    onChange={(e) => setFormData(prev => ({ ...prev, daily_calories: e.target.value }))}
                    placeholder="2000"
                  />
                </div>

                <div className="space-y-2">
                  <Label>Distribuci├│n (%)</Label>
                  <div className="grid grid-cols-3 gap-2">
                    <div>
                      <Label className="text-xs text-gray-500">Prote├¡nas</Label>
                      <Input
                        type="number"
                        value={formData.macros.protein}
                        onChange={(e) => setFormData(prev => ({ 
                          ...prev, 
                          macros: { ...prev.macros, protein: e.target.value }
                        }))}
                      />
                    </div>
                    <div>
                      <Label className="text-xs text-gray-500">Carbs</Label>
                      <Input
                        type="number"
                        value={formData.macros.carbs}
                        onChange={(e) => setFormData(prev => ({ 
                          ...prev, 
                          macros: { ...prev.macros, carbs: e.target.value }
                        }))}
                      />
                    </div>
                    <div>
                      <Label className="text-xs text-gray-500">Grasas</Label>
                      <Input
                        type="number"
                        value={formData.macros.fats}
                        onChange={(e) => setFormData(prev => ({ 
                          ...prev, 
                          macros: { ...prev.macros, fats: e.target.value }
                        }))}
                      />
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Actions */}
            <div className="flex flex-col gap-3">
              <Button
                type="submit"
                className="w-full bg-black hover:bg-gray-800"
                disabled={saving || (!isEditing && !selectedPatient)}
              >
                {saving ? (
                  <Loader2 className="h-4 w-4 animate-spin mr-2" />
                ) : (
                  <Save className="h-4 w-4 mr-2" />
                )}
                {isEditing ? 'Guardar cambios' : 'Crear plan'}
              </Button>
              <Button
                type="button"
                variant="outline"
                className="w-full"
                onClick={() => navigate('/meal-plans')}
              >
                Cancelar
              </Button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuthStore } from '@/stores/authStore';
import { useMealPlanStore } from '@/stores/mealPlanStore';
import { usePatientStore } from '@/stores/patientStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { 
  Plus, 
  MoreVertical, 
  Edit, 
  Trash2, 
  Calendar,
  Flame,
  Users,
  Check,
  Loader2,
  ChevronRight,
  Download
} from 'lucide-react';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import type { MealPlan } from '@/types';
import { exportMealPlanToPDF } from '@/utils/pdfExport';

export function MealPlans() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { mealPlans, loading, fetchMealPlans, deleteMealPlan, activateMealPlan } = useMealPlanStore();
  const { patients } = usePatientStore();
  
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [planToDelete, setPlanToDelete] = useState<MealPlan | null>(null);

  useEffect(() => {
    if (user) {
      fetchMealPlans(user.id);
    }
  }, [user]);

  const handleDelete = async () => {
    if (planToDelete) {
      await deleteMealPlan(planToDelete.id);
      setDeleteDialogOpen(false);
      setPlanToDelete(null);
    }
  };

  const getPatientName = (patientId: string) => {
    const patient = patients.find(p => p.id === patientId);
    return patient ? `${patient.first_name} ${patient.last_name}` : 'Paciente no encontrado';
  };

  const handleExport = (plan: MealPlan) => {
    const patient = patients.find(p => p.id === plan.patient_id);
    if (patient) {
      exportMealPlanToPDF(patient, plan);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Planes de Alimentaci├│n</h1>
          <p className="text-gray-500 mt-1">Gestiona los planes nutricionales de tus pacientes</p>
        </div>
        <Button onClick={() => navigate('/meal-plans/new')} className="bg-black hover:bg-gray-800">
          <Plus className="h-4 w-4 mr-2" />
          Nuevo Plan
        </Button>
      </div>

      {/* Plans List */}
      {loading ? (
        <div className="flex justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
        </div>
      ) : mealPlans.length === 0 ? (
        <Card>
          <CardContent className="text-center py-12">
            <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <Calendar className="h-8 w-8 text-gray-400" />
            </div>
            <h3 className="text-lg font-medium text-gray-900 mb-1">No hay planes registrados</h3>
            <p className="text-gray-500 mb-4">Crea tu primer plan de alimentaci├│n</p>
            <Button onClick={() => navigate('/meal-plans/new')} className="bg-black hover:bg-gray-800">
              <Plus className="h-4 w-4 mr-2" />
              Crear Plan
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {mealPlans.map((plan) => (
            <Card key={plan.id} className="group hover:shadow-lg transition-shadow">
              <CardHeader className="pb-3">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <CardTitle className="text-lg font-semibold">
                        {plan.name}
                      </CardTitle>
                      {plan.is_active && (
                        <Badge className="bg-green-100 text-green-800">
                          <Check className="h-3 w-3 mr-1" />
                          Activo
                        </Badge>
                      )}
                    </div>
                    <p className="text-sm text-gray-500 mt-1">
                      {getPatientName(plan.patient_id)}
                    </p>
                  </div>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon">
                        <MoreVertical className="h-4 w-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      {!plan.is_active && (
                        <DropdownMenuItem onClick={() => activateMealPlan(plan.id)}>
                          <Check className="h-4 w-4 mr-2" />
                          Activar
                        </DropdownMenuItem>
                      )}
                      <DropdownMenuItem onClick={() => navigate(`/meal-plans/${plan.id}/edit`)}>
                        <Edit className="h-4 w-4 mr-2" />
                        Editar
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => handleExport(plan)}>
                        <Download className="h-4 w-4 mr-2" />
                        Exportar PDF
                      </DropdownMenuItem>
                      <DropdownMenuItem 
                        className="text-red-600"
                        onClick={() => {
                          setPlanToDelete(plan);
                          setDeleteDialogOpen(true);
                        }}
                      >
                        <Trash2 className="h-4 w-4 mr-2" />
                        Eliminar
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              </CardHeader>
              <CardContent>
                <div className="flex items-center gap-4 text-sm text-gray-500 mb-4">
                  <div className="flex items-center gap-1">
                    <Flame className="h-4 w-4" />
                    <span>{plan.daily_calories} kcal/d├¡a</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Calendar className="h-4 w-4" />
                    <span>
                      {format(new Date(plan.start_date), "d MMM", { locale: es })}
                      {plan.end_date && ` - ${format(new Date(plan.end_date), "d MMM", { locale: es })}`}
                    </span>
                  </div>
                </div>

                <div className="flex gap-2 mb-4">
                  <Badge variant="secondary">P: {plan.macros.protein}%</Badge>
                  <Badge variant="secondary">C: {plan.macros.carbs}%</Badge>
                  <Badge variant="secondary">G: {plan.macros.fats}%</Badge>
                </div>

                <Button 
                  variant="outline" 
                  className="w-full"
                  onClick={() => navigate(`/meal-plans/${plan.id}`)}
                >
                  Ver plan
                  <ChevronRight className="h-4 w-4 ml-2" />
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>┬┐Eliminar plan?</AlertDialogTitle>
            <AlertDialogDescription>
              Esta acci├│n eliminar├í el plan <strong>{planToDelete?.name}</strong>. Esta acci├│n no se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-red-600 hover:bg-red-700">
              Eliminar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { usePatientStore } from '@/stores/patientStore';
import { useAnamnesisStore } from '@/stores/anamnesisStore';
import { useMealPlanStore } from '@/stores/mealPlanStore';
import { useFollowUpStore } from '@/stores/followUpStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { 
  ArrowLeft, 
  Edit, 
  FileText, 
  Calendar, 
  TrendingUp, 
  Utensils,
  Plus,
  Download,
  Loader2,
  Mail,
  Phone,
  Briefcase,
  Clock,
  Activity
} from 'lucide-react';
import { calculateAge, getBMICategory } from '@/utils/calculations';
import { exportAnamnesisToPDF } from '@/utils/pdfExport';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';

export function PatientDetail() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const { selectedPatient, getPatientById, loading: patientLoading } = usePatientStore();
  const { anamnesisList, fetchAnamnesisByPatient, selectedAnamnesis } = useAnamnesisStore();
  const { mealPlans, fetchMealPlansByPatient } = useMealPlanStore();
  const { followUps, fetchFollowUpsByPatient } = useFollowUpStore();

  const [activeTab, setActiveTab] = useState('overview');

  useEffect(() => {
    if (id) {
      getPatientById(id);
      fetchAnamnesisByPatient(id);
      fetchMealPlansByPatient(id);
      fetchFollowUpsByPatient(id);
    }
  }, [id]);

  const getInitials = (firstName: string, lastName: string) => {
    return `${firstName[0]}${lastName[0]}`.toUpperCase();
  };

  const getStressLevelBadge = (level: string | null) => {
    if (!level) return null;
    
    const configs = {
      low: { label: 'Bajo', className: 'bg-green-100 text-green-800' },
      moderate: { label: 'Moderado', className: 'bg-yellow-100 text-yellow-800' },
      high: { label: 'Alto', className: 'bg-red-100 text-red-800' },
    };
    
    const config = configs[level as keyof typeof configs];
    if (!config) return null;
    
    return <Badge variant="secondary" className={config.className}>{config.label}</Badge>;
  };

  const handleExportAnamnesis = () => {
    if (selectedPatient && selectedAnamnesis) {
      exportAnamnesisToPDF(selectedPatient, selectedAnamnesis);
    }
  };

  if (patientLoading || !selectedPatient) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  const latestAnamnesis = anamnesisList[0];
  const activeMealPlan = mealPlans.find(mp => mp.is_active);
  const latestFollowUp = followUps[0];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => navigate('/patients')}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="flex items-center gap-4">
            <Avatar className="h-16 w-16">
              <AvatarFallback className="bg-black text-white text-xl">
                {getInitials(selectedPatient.first_name, selectedPatient.last_name)}
              </AvatarFallback>
            </Avatar>
            <div>
              <h1 className="text-3xl font-bold text-gray-900">
                {selectedPatient.first_name} {selectedPatient.last_name}
              </h1>
              <div className="flex items-center gap-3 mt-1">
                <span className="text-gray-500">
                  {calculateAge(selectedPatient.birth_date)} a├▒os ÔÇó {' '}
                  {selectedPatient.gender === 'male' ? 'Masculino' : selectedPatient.gender === 'female' ? 'Femenino' : 'Otro'}
                </span>
                {getStressLevelBadge(selectedPatient.stress_level)}
              </div>
            </div>
          </div>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={() => navigate(`/patients/${id}/edit`)}>
            <Edit className="h-4 w-4 mr-2" />
            Editar
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid w-full grid-cols-4 lg:w-auto">
          <TabsTrigger value="overview">Resumen</TabsTrigger>
          <TabsTrigger value="anamnesis">Anamnesis</TabsTrigger>
          <TabsTrigger value="meal-plans">Planes</TabsTrigger>
          <TabsTrigger value="follow-ups">Seguimiento</TabsTrigger>
        </TabsList>

        {/* Overview Tab */}
        <TabsContent value="overview" className="space-y-6">
          {/* Contact Info */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {selectedPatient.email && (
              <Card>
                <CardContent className="pt-6">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg bg-gray-100 flex items-center justify-center">
                      <Mail className="h-5 w-5 text-gray-600" />
                    </div>
                    <div>
                      <p className="text-sm text-gray-500">Email</p>
                      <p className="font-medium text-gray-900">{selectedPatient.email}</p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}
            {selectedPatient.phone && (
              <Card>
                <CardContent className="pt-6">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg bg-gray-100 flex items-center justify-center">
                      <Phone className="h-5 w-5 text-gray-600" />
                    </div>
                    <div>
                      <p className="text-sm text-gray-500">Tel├®fono</p>
                      <p className="font-medium text-gray-900">{selectedPatient.phone}</p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}
            {selectedPatient.occupation && (
              <Card>
                <CardContent className="pt-6">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg bg-gray-100 flex items-center justify-center">
                      <Briefcase className="h-5 w-5 text-gray-600" />
                    </div>
                    <div>
                      <p className="text-sm text-gray-500">Ocupaci├│n</p>
                      <p className="font-medium text-gray-900">{selectedPatient.occupation}</p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}
            {selectedPatient.work_schedule && (
              <Card>
                <CardContent className="pt-6">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg bg-gray-100 flex items-center justify-center">
                      <Clock className="h-5 w-5 text-gray-600" />
                    </div>
                    <div>
                      <p className="text-sm text-gray-500">Horario</p>
                      <p className="font-medium text-gray-900">{selectedPatient.work_schedule}</p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>

          {/* Quick Stats */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {/* Anamnesis Card */}
            <Card>
              <CardHeader className="flex flex-row items-center justify-between">
                <CardTitle className="text-lg font-semibold flex items-center gap-2">
                  <FileText className="h-5 w-5" />
                  Anamnesis
                </CardTitle>
                {latestAnamnesis && (
                  <Button variant="ghost" size="sm" onClick={handleExportAnamnesis}>
                    <Download className="h-4 w-4" />
                  </Button>
                )}
              </CardHeader>
              <CardContent>
                {latestAnamnesis ? (
                  <div className="space-y-4">
                    <div className="grid grid-cols-3 gap-4 text-center">
                      <div>
                        <p className="text-2xl font-bold">{latestAnamnesis.anthropometric_data.weight}</p>
                        <p className="text-xs text-gray-500">kg</p>
                      </div>
                      <div>
                        <p className="text-2xl font-bold">{latestAnamnesis.anthropometric_data.height}</p>
                        <p className="text-xs text-gray-500">cm</p>
                      </div>
                      <div>
                        <p className="text-2xl font-bold">{latestAnamnesis.anthropometric_data.bmi}</p>
                        <p className="text-xs text-gray-500">IMC</p>
                      </div>
                    </div>
                    <Button 
                      variant="outline" 
                      className="w-full"
                      onClick={() => setActiveTab('anamnesis')}
                    >
                      Ver completo
                    </Button>
                  </div>
                ) : (
                  <div className="text-center py-6">
                    <p className="text-gray-500 mb-4">No hay anamnesis registrada</p>
                    <Button onClick={() => navigate(`/patients/${id}/anamnesis/new`)}>
                      <Plus className="h-4 w-4 mr-2" />
                      Crear anamnesis
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Meal Plan Card */}
            <Card>
              <CardHeader className="flex flex-row items-center justify-between">
                <CardTitle className="text-lg font-semibold flex items-center gap-2">
                  <Utensils className="h-5 w-5" />
                  Plan Activo
                </CardTitle>
              </CardHeader>
              <CardContent>
                {activeMealPlan ? (
                  <div className="space-y-4">
                    <div>
                      <p className="font-medium">{activeMealPlan.name}</p>
                      <p className="text-sm text-gray-500">{activeMealPlan.daily_calories} kcal/d├¡a</p>
                    </div>
                    <div className="flex gap-2">
                      <Badge variant="secondary">P: {activeMealPlan.macros.protein}%</Badge>
                      <Badge variant="secondary">C: {activeMealPlan.macros.carbs}%</Badge>
                      <Badge variant="secondary">G: {activeMealPlan.macros.fats}%</Badge>
                    </div>
                    <Button 
                      variant="outline" 
                      className="w-full"
                      onClick={() => setActiveTab('meal-plans')}
                    >
                      Ver plan
                    </Button>
                  </div>
                ) : (
                  <div className="text-center py-6">
                    <p className="text-gray-500 mb-4">No hay plan activo</p>
                    <Button onClick={() => navigate(`/patients/${id}/meal-plans/new`)}>
                      <Plus className="h-4 w-4 mr-2" />
                      Crear plan
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Follow Up Card */}
            <Card>
              <CardHeader className="flex flex-row items-center justify-between">
                <CardTitle className="text-lg font-semibold flex items-center gap-2">
                  <TrendingUp className="h-5 w-5" />
                  ├Ültimo Control
                </CardTitle>
              </CardHeader>
              <CardContent>
                {latestFollowUp ? (
                  <div className="space-y-4">
                    <div>
                      <p className="text-2xl font-bold">{latestFollowUp.weight} kg</p>
                      <p className="text-sm text-gray-500">
                        {format(new Date(latestFollowUp.date), "d 'de' MMMM", { locale: es })}
                      </p>
                    </div>
                    {latestFollowUp.adherence && (
                      <Badge variant="secondary">
                        Adherencia: {latestFollowUp.adherence === 'excellent' ? 'Excelente' : 
                                    latestFollowUp.adherence === 'good' ? 'Buena' : 
                                    latestFollowUp.adherence === 'fair' ? 'Regular' : 'Deficiente'}
                      </Badge>
                    )}
                    <Button 
                      variant="outline" 
                      className="w-full"
                      onClick={() => setActiveTab('follow-ups')}
                    >
                      Ver historial
                    </Button>
                  </div>
                ) : (
                  <div className="text-center py-6">
                    <p className="text-gray-500 mb-4">No hay controles registrados</p>
                    <Button onClick={() => navigate(`/patients/${id}/follow-ups/new`)}>
                      <Plus className="h-4 w-4 mr-2" />
                      Registrar control
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        {/* Anamnesis Tab */}
        <TabsContent value="anamnesis">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle className="text-lg font-semibold">Anamnesis Nutricional</CardTitle>
              <div className="flex gap-2">
                {latestAnamnesis && (
                  <Button variant="outline" onClick={handleExportAnamnesis}>
                    <Download className="h-4 w-4 mr-2" />
                    Exportar PDF
                  </Button>
                )}
                <Button onClick={() => navigate(`/patients/${id}/anamnesis/new`)}>
                  <Plus className="h-4 w-4 mr-2" />
                  {latestAnamnesis ? 'Actualizar' : 'Crear'}
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              {latestAnamnesis ? (
                <div className="space-y-8">
                  {/* Anthropometric Data */}
                  <div>
                    <h3 className="text-lg font-semibold mb-4">Datos Antropom├®tricos</h3>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div className="p-4 bg-gray-50 rounded-lg">
                        <p className="text-sm text-gray-500">Peso</p>
                        <p className="text-2xl font-bold">{latestAnamnesis.anthropometric_data.weight} <span className="text-sm font-normal">kg</span></p>
                      </div>
                      <div className="p-4 bg-gray-50 rounded-lg">
                        <p className="text-sm text-gray-500">Altura</p>
                        <p className="text-2xl font-bold">{latestAnamnesis.anthropometric_data.height} <span className="text-sm font-normal">cm</span></p>
                      </div>
                      <div className="p-4 bg-gray-50 rounded-lg">
                        <p className="text-sm text-gray-500">IMC</p>
                        <p className="text-2xl font-bold">{latestAnamnesis.anthropometric_data.bmi}</p>
                        <p className="text-xs text-gray-500">{getBMICategory(latestAnamnesis.anthropometric_data.bmi).label}</p>
                      </div>
                      {latestAnamnesis.anthropometric_data.body_fat_percentage && (
                        <div className="p-4 bg-gray-50 rounded-lg">
                          <p className="text-sm text-gray-500">% Grasa</p>
                          <p className="text-2xl font-bold">{latestAnamnesis.anthropometric_data.body_fat_percentage}%</p>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Consultation Reason */}
                  <div>
                    <h3 className="text-lg font-semibold mb-2">Motivo de Consulta</h3>
                    <p className="text-gray-700">{latestAnamnesis.consultation_reason || 'No especificado'}</p>
                  </div>

                  {/* Diseases */}
                  {latestAnamnesis.diseases?.length > 0 && (
                    <div>
                      <h3 className="text-lg font-semibold mb-2">Enfermedades</h3>
                      <div className="flex flex-wrap gap-2">
                        {latestAnamnesis.diseases.map((disease, index) => (
                          <Badge key={index} variant="secondary">{disease}</Badge>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* Medications */}
                  {latestAnamnesis.medications?.length > 0 && (
                    <div>
                      <h3 className="text-lg font-semibold mb-2">Medicaci├│n</h3>
                      <ul className="space-y-2">
                        {latestAnamnesis.medications.map((med, index) => (
                          <li key={index} className="text-gray-700">
                            ÔÇó {med.name} {med.dosage && `- ${med.dosage}`} {med.frequency && `(${med.frequency})`}
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {/* Eating Habits */}
                  {latestAnamnesis.eating_habits && (
                    <div>
                      <h3 className="text-lg font-semibold mb-2">H├íbitos Alimentarios</h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {latestAnamnesis.eating_habits.meal_frequency && (
                          <div>
                            <p className="text-sm text-gray-500">Comidas por d├¡a</p>
                            <p className="font-medium">{latestAnamnesis.eating_habits.meal_frequency}</p>
                          </div>
                        )}
                        {latestAnamnesis.eating_habits.allergies?.length > 0 && (
                          <div>
                            <p className="text-sm text-gray-500">Alergias</p>
                            <p className="font-medium">{latestAnamnesis.eating_habits.allergies.join(', ')}</p>
                          </div>
                        )}
                        {latestAnamnesis.eating_habits.intolerances?.length > 0 && (
                          <div>
                            <p className="text-sm text-gray-500">Intolerancias</p>
                            <p className="font-medium">{latestAnamnesis.eating_habits.intolerances.join(', ')}</p>
                          </div>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              ) : (
                <div className="text-center py-12">
                  <FileText className="h-12 w-12 mx-auto mb-4 text-gray-300" />
                  <h3 className="text-lg font-medium text-gray-900 mb-2">No hay anamnesis registrada</h3>
                  <p className="text-gray-500 mb-4">Crea una anamnesis para comenzar el seguimiento nutricional</p>
                  <Button onClick={() => navigate(`/patients/${id}/anamnesis/new`)}>
                    <Plus className="h-4 w-4 mr-2" />
                    Crear Anamnesis
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Meal Plans Tab */}
        <TabsContent value="meal-plans">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle className="text-lg font-semibold">Planes de Alimentaci├│n</CardTitle>
              <Button onClick={() => navigate(`/patients/${id}/meal-plans/new`)}>
                <Plus className="h-4 w-4 mr-2" />
                Nuevo Plan
              </Button>
            </CardHeader>
            <CardContent>
              {mealPlans.length === 0 ? (
                <div className="text-center py-12">
                  <Utensils className="h-12 w-12 mx-auto mb-4 text-gray-300" />
                  <h3 className="text-lg font-medium text-gray-900 mb-2">No hay planes registrados</h3>
                  <p className="text-gray-500 mb-4">Crea un plan de alimentaci├│n personalizado</p>
                  <Button onClick={() => navigate(`/patients/${id}/meal-plans/new`)}>
                    <Plus className="h-4 w-4 mr-2" />
                    Crear Plan
                  </Button>
                </div>
              ) : (
                <div className="space-y-4">
                  {mealPlans.map((plan) => (
                    <div 
                      key={plan.id}
                      className="flex items-center justify-between p-4 border rounded-lg hover:bg-gray-50 cursor-pointer"
                      onClick={() => navigate(`/patients/${id}/meal-plans/${plan.id}`)}
                    >
                      <div>
                        <div className="flex items-center gap-2">
                          <p className="font-medium">{plan.name}</p>
                          {plan.is_active && <Badge>Activo</Badge>}
                        </div>
                        <p className="text-sm text-gray-500">
                          {plan.daily_calories} kcal/d├¡a ÔÇó P:{plan.macros.protein}% C:{plan.macros.carbs}% G:{plan.macros.fats}%
                        </p>
                      </div>
                      <Button variant="ghost" size="sm">
                        Ver detalle
                      </Button>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Follow Ups Tab */}
        <TabsContent value="follow-ups">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle className="text-lg font-semibold">Seguimiento</CardTitle>
              <Button onClick={() => navigate(`/patients/${id}/follow-ups/new`)}>
                <Plus className="h-4 w-4 mr-2" />
                Nuevo Control
              </Button>
            </CardHeader>
            <CardContent>
              {followUps.length === 0 ? (
                <div className="text-center py-12">
                  <Activity className="h-12 w-12 mx-auto mb-4 text-gray-300" />
                  <h3 className="text-lg font-medium text-gray-900 mb-2">No hay controles registrados</h3>
                  <p className="text-gray-500 mb-4">Registra el progreso de tu paciente</p>
                  <Button onClick={() => navigate(`/patients/${id}/follow-ups/new`)}>
                    <Plus className="h-4 w-4 mr-2" />
                    Registrar Control
                  </Button>
                </div>
              ) : (
                <div className="space-y-4">
                  {followUps.map((followUp) => (
                    <div 
                      key={followUp.id}
                      className="flex items-center justify-between p-4 border rounded-lg hover:bg-gray-50 cursor-pointer"
                      onClick={() => navigate(`/patients/${id}/follow-ups/${followUp.id}`)}
                    >
                      <div>
                        <p className="font-medium">
                          {format(new Date(followUp.date), "d 'de' MMMM, yyyy", { locale: es })}
                        </p>
                        <p className="text-sm text-gray-500">
                          Peso: {followUp.weight} kg {followUp.adherence && `ÔÇó Adherencia: ${followUp.adherence}`}
                        </p>
                      </div>
                      <Button variant="ghost" size="sm">
                        Ver detalle
                      </Button>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAuthStore } from '@/stores/authStore';
import { usePatientStore } from '@/stores/patientStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { ArrowLeft, Loader2, Save } from 'lucide-react';
import type { PatientFormData } from '@/types';

const initialFormData: PatientFormData = {
  first_name: '',
  last_name: '',
  email: '',
  phone: '',
  birth_date: '',
  gender: 'male',
  occupation: '',
  work_schedule: '',
  stress_level: '',
};

export function PatientForm() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const { user } = useAuthStore();
  const { selectedPatient, createPatient, updatePatient, getPatientById, loading } = usePatientStore();
  
  const isEditing = Boolean(id);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState<PatientFormData>(initialFormData);

  useEffect(() => {
    if (isEditing && id) {
      getPatientById(id);
    }
  }, [id, isEditing]);

  useEffect(() => {
    if (isEditing && selectedPatient) {
      setFormData({
        first_name: selectedPatient.first_name,
        last_name: selectedPatient.last_name,
        email: selectedPatient.email || '',
        phone: selectedPatient.phone || '',
        birth_date: selectedPatient.birth_date,
        gender: selectedPatient.gender,
        occupation: selectedPatient.occupation || '',
        work_schedule: selectedPatient.work_schedule || '',
        stress_level: selectedPatient.stress_level || '',
      });
    }
  }, [selectedPatient, isEditing]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    setSaving(true);
    
    try {
      const dataToSave = {
        ...formData,
        stress_level: (formData.stress_level as string) === 'unspecified' ? '' : formData.stress_level
      };

      if (isEditing && id) {
        await updatePatient(id, dataToSave as PatientFormData);
      } else {
        await createPatient(user.id, dataToSave as PatientFormData);
      }
      navigate('/patients');
    } catch (error) {
      console.error('Error saving patient:', error);
    } finally {
      setSaving(false);
    }
  };

  const handleChange = (field: keyof PatientFormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  if (isEditing && loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => navigate('/patients')}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-3xl font-bold text-gray-900">
            {isEditing ? 'Editar Paciente' : 'Nuevo Paciente'}
          </h1>
          <p className="text-gray-500 mt-1">
            {isEditing 
              ? 'Actualiza la informaci├│n del paciente' 
              : 'Completa los datos para registrar un nuevo paciente'}
          </p>
        </div>
      </div>

      <form onSubmit={handleSubmit}>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Personal Information */}
          <Card>
            <CardHeader>
              <CardTitle className="text-lg font-semibold">Informaci├│n Personal</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="first_name">Nombre *</Label>
                  <Input
                    id="first_name"
                    value={formData.first_name}
                    onChange={(e) => handleChange('first_name', e.target.value)}
                    required
                    placeholder="Juan"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="last_name">Apellido *</Label>
                  <Input
                    id="last_name"
                    value={formData.last_name}
                    onChange={(e) => handleChange('last_name', e.target.value)}
                    required
                    placeholder="P├®rez"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="email">Correo electr├│nico</Label>
                <Input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => handleChange('email', e.target.value)}
                  placeholder="paciente@email.com"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="phone">Tel├®fono</Label>
                <Input
                  id="phone"
                  type="tel"
                  value={formData.phone}
                  onChange={(e) => handleChange('phone', e.target.value)}
                  placeholder="+54 11 1234-5678"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="birth_date">Fecha de nacimiento *</Label>
                <Input
                  id="birth_date"
                  type="date"
                  value={formData.birth_date}
                  onChange={(e) => handleChange('birth_date', e.target.value)}
                  required
                />
              </div>

              <div className="space-y-2">
                <Label>Sexo *</Label>
                <RadioGroup
                  value={formData.gender}
                  onValueChange={(value) => handleChange('gender', value as 'male' | 'female' | 'other')}
                  className="flex gap-4"
                >
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="male" id="male" />
                    <Label htmlFor="male" className="cursor-pointer">Masculino</Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="female" id="female" />
                    <Label htmlFor="female" className="cursor-pointer">Femenino</Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="other" id="other" />
                    <Label htmlFor="other" className="cursor-pointer">Otro</Label>
                  </div>
                </RadioGroup>
              </div>
            </CardContent>
          </Card>

          {/* Additional Information */}
          <Card>
            <CardHeader>
              <CardTitle className="text-lg font-semibold">Informaci├│n Adicional</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="occupation">Ocupaci├│n</Label>
                <Input
                  id="occupation"
                  value={formData.occupation}
                  onChange={(e) => handleChange('occupation', e.target.value)}
                  placeholder="Ej: Ingeniero, Estudiante..."
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="work_schedule">Horario de trabajo</Label>
                <Input
                  id="work_schedule"
                  value={formData.work_schedule}
                  onChange={(e) => handleChange('work_schedule', e.target.value)}
                  placeholder="Ej: 9:00 - 18:00, turno rotativo..."
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="stress_level">Nivel de estr├®s</Label>
                <Select
                  value={formData.stress_level}
                  onValueChange={(value) => handleChange('stress_level', value)}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Seleccionar nivel de estr├®s" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="unspecified">No especificado</SelectItem>
                    <SelectItem value="low">Bajo</SelectItem>
                    <SelectItem value="moderate">Moderado</SelectItem>
                    <SelectItem value="high">Alto</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Actions */}
        <div className="flex justify-end gap-4 mt-6">
          <Button
            type="button"
            variant="outline"
            onClick={() => navigate('/patients')}
          >
            Cancelar
          </Button>
          <Button
            type="submit"
            className="bg-black hover:bg-gray-800"
            disabled={saving}
          >
            {saving ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : (
              <Save className="h-4 w-4 mr-2" />
            )}
            {isEditing ? 'Guardar cambios' : 'Crear paciente'}
          </Button>
        </div>
      </form>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuthStore } from '@/stores/authStore';
import { usePatientStore } from '@/stores/patientStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { 
  Search, 
  Plus, 
  MoreVertical, 
  Edit, 
  Trash2, 
  FileText, 
  Calendar,
  TrendingUp,
  Utensils,
  ChevronRight,
  Loader2
} from 'lucide-react';
import { calculateAge } from '@/utils/calculations';
import type { PatientWithAge } from '@/types';

export function Patients() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { patients, loading, fetchPatients, deletePatient, setSearchQuery, filteredPatients } = usePatientStore();
  
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [patientToDelete, setPatientToDelete] = useState<PatientWithAge | null>(null);
  const [searchValue, setSearchValue] = useState('');

  useEffect(() => {
    if (user) {
      fetchPatients(user.id);
    }
  }, [user]);

  useEffect(() => {
    const timeout = setTimeout(() => {
      setSearchQuery(searchValue);
    }, 300);
    return () => clearTimeout(timeout);
  }, [searchValue]);

  const handleDelete = async () => {
    if (patientToDelete) {
      await deletePatient(patientToDelete.id);
      setDeleteDialogOpen(false);
      setPatientToDelete(null);
    }
  };

  const getInitials = (firstName: string, lastName: string) => {
    return `${firstName[0]}${lastName[0]}`.toUpperCase();
  };

  const getStressLevelBadge = (level: string | null) => {
    if (!level) return null;
    
    const configs = {
      low: { label: 'Bajo', className: 'bg-green-100 text-green-800' },
      moderate: { label: 'Moderado', className: 'bg-yellow-100 text-yellow-800' },
      high: { label: 'Alto', className: 'bg-red-100 text-red-800' },
    };
    
    const config = configs[level as keyof typeof configs];
    if (!config) return null;
    
    return <Badge variant="secondary" className={config.className}>{config.label}</Badge>;
  };

  const displayedPatients = filteredPatients();

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Pacientes</h1>
          <p className="text-gray-500 mt-1">Gestiona tus pacientes y su informaci├│n</p>
        </div>
        <Button onClick={() => navigate('/patients/new')} className="bg-black hover:bg-gray-800">
          <Plus className="h-4 w-4 mr-2" />
          Nuevo Paciente
        </Button>
      </div>

      {/* Search */}
      <Card>
        <CardContent className="pt-6">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <Input
              placeholder="Buscar por nombre, email o tel├®fono..."
              value={searchValue}
              onChange={(e) => setSearchValue(e.target.value)}
              className="pl-10 h-11"
            />
          </div>
        </CardContent>
      </Card>

      {/* Patients List */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg font-semibold">
            {displayedPatients.length} {displayedPatients.length === 1 ? 'paciente' : 'pacientes'}
          </CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
            </div>
          ) : displayedPatients.length === 0 ? (
            <div className="text-center py-12">
              <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <Search className="h-8 w-8 text-gray-400" />
              </div>
              <h3 className="text-lg font-medium text-gray-900 mb-1">
                {searchValue ? 'No se encontraron pacientes' : 'No hay pacientes registrados'}
              </h3>
              <p className="text-gray-500 mb-4">
                {searchValue 
                  ? 'Intenta con otros t├®rminos de b├║squeda' 
                  : 'Comienza agregando tu primer paciente'}
              </p>
              {!searchValue && (
                <Button onClick={() => navigate('/patients/new')} className="bg-black hover:bg-gray-800">
                  <Plus className="h-4 w-4 mr-2" />
                  Agregar Paciente
                </Button>
              )}
            </div>
          ) : (
            <div className="divide-y divide-gray-100">
              {displayedPatients.map((patient) => (
                <div 
                  key={patient.id}
                  className="flex items-center justify-between py-4 group"
                >
                  <div 
                    className="flex items-center gap-4 flex-1 cursor-pointer"
                    onClick={() => navigate(`/patients/${patient.id}`)}
                  >
                    <Avatar className="h-12 w-12">
                      <AvatarFallback className="bg-gray-200 text-gray-700">
                        {getInitials(patient.first_name, patient.last_name)}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1">
                      <div className="flex items-center gap-3">
                        <h3 className="font-semibold text-gray-900">
                          {patient.first_name} {patient.last_name}
                        </h3>
                        {getStressLevelBadge(patient.stress_level)}
                      </div>
                      <div className="flex items-center gap-4 mt-1 text-sm text-gray-500">
                        <span>{patient.age} a├▒os</span>
                        <span>ÔÇó</span>
                        <span>{patient.gender === 'male' ? 'Masculino' : patient.gender === 'female' ? 'Femenino' : 'Otro'}</span>
                        {patient.email && (
                          <>
                            <span>ÔÇó</span>
                            <span>{patient.email}</span>
                          </>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => navigate(`/patients/${patient.id}/anamnesis`)}
                      className="hidden sm:flex"
                    >
                      <FileText className="h-4 w-4 mr-2" />
                      Anamnesis
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => navigate(`/patients/${patient.id}/meal-plans`)}
                      className="hidden sm:flex"
                    >
                      <Utensils className="h-4 w-4 mr-2" />
                      Plan
                    </Button>

                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon">
                          <MoreVertical className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => navigate(`/patients/${patient.id}`)}>
                          <ChevronRight className="h-4 w-4 mr-2" />
                          Ver detalle
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => navigate(`/patients/${patient.id}/edit`)}>
                          <Edit className="h-4 w-4 mr-2" />
                          Editar
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => navigate(`/patients/${patient.id}/anamnesis`)}>
                          <FileText className="h-4 w-4 mr-2" />
                          Anamnesis
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => navigate(`/patients/${patient.id}/meal-plans`)}>
                          <Calendar className="h-4 w-4 mr-2" />
                          Plan de alimentaci├│n
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => navigate(`/patients/${patient.id}/follow-ups`)}>
                          <TrendingUp className="h-4 w-4 mr-2" />
                          Seguimiento
                        </DropdownMenuItem>
                        <DropdownMenuItem 
                          className="text-red-600"
                          onClick={() => {
                            setPatientToDelete(patient);
                            setDeleteDialogOpen(true);
                          }}
                        >
                          <Trash2 className="h-4 w-4 mr-2" />
                          Eliminar
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>┬┐Eliminar paciente?</AlertDialogTitle>
            <AlertDialogDescription>
              Esta acci├│n eliminar├í a <strong>{patientToDelete?.first_name} {patientToDelete?.last_name}</strong> y todos sus datos asociados (anamnesis, planes, seguimientos). Esta acci├│n no se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-red-600 hover:bg-red-700">
              Eliminar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useAuthStore } from '@/stores/authStore';
import { User, Save, Loader2, ShieldCheck, Mail } from 'lucide-react';
import { toast } from 'sonner';

export function Profile() {
  const { user, updateProfile } = useAuthStore();
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState({
    title: '',
    full_name: '',
  });

  useEffect(() => {
    if (user) {
      const nameParts = (user.full_name || '').split(' ');
      const knownTitles = ['Lic.', 'Dr.', 'Dra.', 'Nut.', 'Nutricionista'];
      let possibleTitle = '';
      let restOfName = user.full_name || '';

      if (nameParts.length > 0 && knownTitles.includes(nameParts[0])) {
        possibleTitle = nameParts[0];
        restOfName = nameParts.slice(1).join(' ');
      }

      setFormData({
        title: possibleTitle,
        full_name: restOfName,
      });
    }
  }, [user]);

  const handleSave = async () => {
    if (!user) return;
    setSaving(true);
    
    const finalFullName = formData.title 
      ? `${formData.title} ${formData.full_name.trim()}`
      : formData.full_name.trim();

    const { error } = await updateProfile({
      full_name: finalFullName,
    } as any);

    if (error) {
      toast.error(typeof error === 'string' ? error : 'Error al actualizar el perfil');
    } else {
      toast.success('Perfil actualizado correctamente');
    }
    setSaving(false);
  };

  return (
    <div className="space-y-10 max-w-5xl mx-auto animate-in fade-in duration-700">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6 pb-2 border-b border-zinc-100">
        <div className="space-y-1.5">
          <h1 className="text-4xl font-extrabold text-zinc-900 tracking-tight">Mi Perfil</h1>
          <p className="text-zinc-500 text-lg font-medium">Administra tu informaci├│n personal y credenciales de acceso a la plataforma</p>
        </div>
        <Button onClick={handleSave} disabled={saving} className="bg-emerald-600 hover:bg-emerald-700 hover:-translate-y-0.5 hover:shadow-lg text-white shadow-md transition-all duration-300 px-6 h-12 rounded-xl text-base">
          {saving ? <Loader2 className="h-5 w-5 mr-2 animate-spin" /> : <Save className="h-5 w-5 mr-2" />}
          Guardar Cambios
        </Button>
      </div>

      <div className="space-y-12 divide-y divide-zinc-200 mt-8">
        
        {/* Identidad Setup */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 lg:gap-12 pt-8">
          <div className="md:col-span-1 space-y-4">
            <div className="p-3 bg-emerald-50 rounded-2xl w-fit">
              <User className="h-6 w-6 text-emerald-600" />
            </div>
            <div>
              <h3 className="text-xl font-bold text-zinc-900 tracking-tight">Perfil e Identidad</h3>
              <p className="text-sm font-medium text-zinc-500 mt-2 leading-relaxed">
                Informaci├│n p├║blica que se mostrar├í en los comunicados a tus pacientes y en tu cat├ílogo p├║blico.
              </p>
            </div>
          </div>
          
          <div className="md:col-span-2">
            <Card className="border-zinc-200 shadow-sm transition-all duration-300 rounded-3xl overflow-hidden bg-white">
              <CardContent className="p-6 sm:p-8 space-y-8">
                {/* Avatar Row */}
                <div className="flex flex-col sm:flex-row items-center sm:items-start gap-6">
                  <div className="flex-shrink-0 relative">
                    <div className="w-28 h-28 bg-emerald-50 rounded-full flex items-center justify-center border border-emerald-100 shadow-inner">
                      <span className="text-4xl font-extrabold text-emerald-600 tracking-tighter">
                        {user?.full_name?.split(' ').map((n: string) => n[0]).join('').toUpperCase().slice(0, 2) || 'U'}
                      </span>
                    </div>
                    <div className="absolute -bottom-2 -right-2 bg-emerald-100 text-emerald-700 p-1.5 rounded-full border-2 border-white shadow-sm" title="Profesional Verificado">
                      <ShieldCheck className="h-5 w-5" />
                    </div>
                  </div>
                  
                  <div className="flex-1 space-y-5 text-center sm:text-left w-full pt-2">
                    <div className="flex flex-col sm:flex-row gap-4 w-full">
                      <div className="space-y-2 w-full sm:w-1/3">
                        <Label htmlFor="title" className="text-sm font-bold text-zinc-700 text-left block">T├¡tulo</Label>
                        <select 
                          id="title"
                          value={formData.title}
                          onChange={e => setFormData({...formData, title: e.target.value})}
                          className="h-14 w-full border border-zinc-200 focus:ring-emerald-600 focus:border-emerald-600 rounded-xl shadow-sm transition-all duration-200 text-base px-3 bg-white"
                        >
                          <option value="">Sin t├¡tulo</option>
                          <option value="Lic.">Licenciada/o</option>
                          <option value="Dr.">Doctor</option>
                          <option value="Dra.">Doctora</option>
                          <option value="Nut.">Nutricionista</option>
                        </select>
                      </div>
                      <div className="space-y-2 w-full sm:w-2/3">
                        <Label htmlFor="full_name" className="text-sm font-bold text-zinc-700 text-left block">Nombre Completo</Label>
                        <Input 
                          id="full_name" 
                          value={formData.full_name} 
                          onChange={e => setFormData({...formData, full_name: e.target.value})}
                          placeholder="Mar├¡a P├®rez" 
                          className="h-14 w-full border-zinc-200 focus:ring-emerald-600 focus:border-emerald-600 rounded-xl shadow-sm transition-all duration-200 text-base"
                        />
                      </div>
                    </div>
                    <p className="text-xs font-bold text-emerald-700 flex items-center justify-center sm:justify-start gap-1.5 mt-2">
                      Tus datos biogr├íficos han sido verificados satisfactoriamente.
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>

        {/* Credentials Setup */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 lg:gap-12 pt-12">
          <div className="md:col-span-1 space-y-4">
            <div className="p-3 bg-zinc-100 rounded-2xl w-fit">
              <Mail className="h-6 w-6 text-zinc-700" />
            </div>
            <div>
              <h3 className="text-xl font-bold text-zinc-900 tracking-tight">Acceso y Seguridad</h3>
              <p className="text-sm font-medium text-zinc-500 mt-2 leading-relaxed">
                Credenciales exclusivas que utilizas para el inicio de sesi├│n autorizado en Nutrixa.
              </p>
            </div>
          </div>
          
          <div className="md:col-span-2">
            <Card className="border-zinc-200 shadow-sm transition-all duration-300 rounded-3xl overflow-hidden bg-white">
              <CardContent className="p-6 sm:p-8">
                <div className="space-y-3">
                  <Label htmlFor="email" className="text-sm font-bold text-zinc-700">Correo Electr├│nico Registrado</Label>
                  <Input 
                    id="email" 
                    value={user?.email || ''} 
                    disabled 
                    className="h-14 w-full bg-zinc-50 text-zinc-500 cursor-not-allowed opacity-80 border-zinc-200 rounded-xl shadow-sm text-base" 
                  />
                  <div className="flex items-start gap-2 bg-amber-50 text-amber-800 p-4 rounded-xl border border-amber-200 shadow-sm mt-4">
                    <ShieldCheck className="h-5 w-5 mt-0.5 flex-shrink-0" />
                    <p className="text-sm font-medium leading-relaxed">
                      La modificaci├│n del correo electr├│nico maestral est├í deshabilitada temporalmente por pol├¡ticas de seguridad estrictas en tu cuenta.
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { supabase } from '@/lib/supabase/client';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Calendar } from '@/components/ui/calendar';
import { es } from 'date-fns/locale';
import { format, addMinutes, parse, isBefore, startOfToday } from 'date-fns';
import type { User, NutritionService } from '@/types';
import { Loader2, Calendar as CalendarIcon, Clock, CheckCircle2, ChevronLeft } from 'lucide-react';
import { toast } from 'sonner';

export function PublicBooking() {
  const { slug } = useParams<{ slug: string }>();
  const [nutritionist, setNutritionist] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Booking state
  const [step, setStep] = useState<'service' | 'datetime'>('service');
  const [selectedService, setSelectedService] = useState<NutritionService | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);
  const [selectedTime, setSelectedTime] = useState<string | null>(null);
  const [availableSlots, setAvailableSlots] = useState<string[]>([]);
  const [loadingSlots, setLoadingSlots] = useState(false);
  
  // Guest info state
  const [guestInfo, setGuestInfo] = useState({ name: '', email: '', phone: '' });
  const [booking, setBooking] = useState(false);
  const [success, setSuccess] = useState(false);

  // Fetch nutritionist profile by slug
  useEffect(() => {
    async function fetchProfile() {
      if (!slug) return;
      try {
        const { data, error } = await supabase
          .from('users')
          .select('*')
          .eq('slug', slug)
          .single();

        if (error) throw error;
        if (!data) throw new Error('Nutricionista no encontrado');
        setNutritionist(data as User);
      } catch (err: any) {
        setError('No pudimos encontrar el perfil de este profesional.');
      } finally {
        setLoading(false);
      }
    }
    fetchProfile();
  }, [slug]);

  // Generate available slots when a date is selected
  useEffect(() => {
    async function fetchSlots() {
      if (!selectedDate || !nutritionist || !selectedService) return;
      
      const dayOfWeek = selectedDate.getDay() === 0 ? 7 : selectedDate.getDay();
      
      // Check if nutritionist works on this day
      if (!nutritionist.working_days?.includes(dayOfWeek)) {
        setAvailableSlots([]);
        return;
      }

      setLoadingSlots(true);
      try {
        const dateStr = format(selectedDate, 'yyyy-MM-dd');
        
        // Fetch existing appointments using secure RPC to avoid RLS locks and protect patient privacy
        const { data: existingAppts } = await (supabase as any)
          .rpc('get_booked_slots', { 
            p_nutritionist_id: nutritionist.id,
            p_date: dateStr
          });

        const parseTime = (timeStr: string) => {
          return parse(timeStr.substring(0, 5), 'HH:mm', new Date());
        };

        const startTime = parseTime(nutritionist.working_hours_start);
        const endTime = parseTime(nutritionist.working_hours_end);
        const duration = Number(selectedService.duration);
        
        const slots: string[] = [];
        let current = startTime;
        let loopGuard = 0; // Anti infinite loop

        // If something was parsed to an invalid date, exit immediately
        if (isNaN(startTime.getTime()) || isNaN(endTime.getTime()) || duration <= 0) {
          setAvailableSlots([]);
          return;
        }

        while (addMinutes(current, duration) <= endTime && loopGuard < 150) {
          loopGuard++;
          const timeString = format(current, 'HH:mm');
          // Basic overlap check
          const isBooked = existingAppts?.some((appt: any) => {
            const apptStart = parseTime(appt.start_time);
            const apptEnd = parseTime(appt.end_time);
            const currentEnd = addMinutes(current, duration);
            
            return (
              (isBefore(current, apptEnd) || current.getTime() === apptEnd.getTime()) && 
              isBefore(apptStart, currentEnd)
            );
          });

          // Also check if time is in the past for today
          const isToday = format(selectedDate, 'yyyy-MM-dd') === format(new Date(), 'yyyy-MM-dd');
          const isPast = isToday && isBefore(current, new Date());

          if (!isBooked && !isPast) {
            slots.push(timeString);
          }
          current = addMinutes(current, duration); // or a 15 min step, but we step by duration to avoid weird math
        }

        setAvailableSlots(slots);
      } catch (err) {
        console.error('Error fetching slots:', err);
      } finally {
        setLoadingSlots(false);
      }
    }
    
    fetchSlots();
    setSelectedTime(null);
  }, [selectedDate, nutritionist, selectedService]);

  const handleBook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDate || !selectedTime || !nutritionist || !selectedService) return;

    setBooking(true);
    try {
      const dateStr = format(selectedDate, 'yyyy-MM-dd');
      const startDateTime = parse(selectedTime, 'HH:mm', new Date());
      const endDateTime = addMinutes(startDateTime, selectedService.duration);

      const { error } = await (supabase as any)
        .from('appointments')
        .insert([{
          nutritionist_id: nutritionist.id,
          guest_name: guestInfo.name,
          guest_email: guestInfo.email,
          guest_phone: guestInfo.phone,
          service_name: selectedService.name,
          service_duration: selectedService.duration,
          service_price: selectedService.price,
          date: dateStr,
          start_time: selectedTime,
          end_time: format(endDateTime, 'HH:mm'),
          status: 'pending' // Nutritionist can confirm it later
        }]);

      if (error) throw error;
      setSuccess(true);
    } catch (err: any) {
      toast.error('Hubo un problema al reservar el turno. Intenta nuevamente.');
    } finally {
      setBooking(false);
    }
  };

  const selectService = (service: NutritionService) => {
    setSelectedService(service);
    setStep('datetime');
    setSelectedDate(undefined);
    setSelectedTime(null);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-zinc-50">
        <Loader2 className="h-8 w-8 animate-spin text-zinc-400" />
      </div>
    );
  }

  if (error || !nutritionist) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-zinc-50 flex-col gap-4">
        <div className="text-4xl text-zinc-300">­ƒöì</div>
        <h2 className="text-xl font-bold text-zinc-700">{error || 'No encontrado'}</h2>
        <p className="text-zinc-500 font-medium">Revisa que el enlace sea correcto.</p>
      </div>
    );
  }

  if (success) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-zinc-50 p-4">
        <Card className="max-w-md w-full text-center py-8 rounded-3xl border-zinc-200 shadow-[0_8px_30px_rgb(0,0,0,0.06)] bg-white overflow-hidden">
          <CardContent className="space-y-6 pt-6">
            <div className="w-20 h-20 bg-emerald-50 rounded-full flex items-center justify-center mx-auto mb-2 border border-emerald-100 shadow-inner">
               <CheckCircle2 className="h-10 w-10 text-emerald-600" />
            </div>
            <div>
               <h2 className="text-3xl font-extrabold text-zinc-900 tracking-tight">┬íTurno Solicitado!</h2>
               <p className="text-sm font-medium text-zinc-500 mt-2 px-4 leading-relaxed">
                 Hemos enviado tu solicitud. {nutritionist.full_name} se pondr├í en contacto pronto para confirmar.
               </p>
            </div>
            
            <div className="bg-zinc-50 mx-4 p-5 rounded-2xl border border-zinc-200 text-left space-y-3 shadow-inner">
              <p className="font-bold text-zinc-900 text-lg border-b border-zinc-200 pb-3">{selectedService?.name}</p>
              <div className="flex items-center gap-3 text-sm font-medium text-zinc-600 pt-1">
                <CalendarIcon className="h-5 w-5 text-emerald-600" />
                <span>{selectedDate && format(selectedDate, "EEEE d 'de' MMMM, yyyy", { locale: es })}</span>
              </div>
              <div className="flex items-center gap-3 text-sm font-medium text-zinc-600">
                <Clock className="h-5 w-5 text-emerald-600" />
                <span>A las {selectedTime} hs</span>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  const hasServices = nutritionist.services && nutritionist.services.length > 0;

  return (
    <div className="min-h-screen bg-zinc-50 flex">
      {/* Left Panel - Premium visual */}
      <div className="hidden lg:flex lg:w-5/12 relative bg-zinc-950 overflow-hidden flex-col justify-between">
        {/* Abstract Backgrounds */}
        <div className="absolute -top-32 -left-32 w-96 h-96 bg-emerald-600 rounded-full mix-blend-screen filter blur-[100px] opacity-30" />
        <div className="absolute top-1/4 -right-32 w-96 h-96 bg-emerald-600 rounded-full mix-blend-screen filter blur-[100px] opacity-20" />
        <div className="absolute -bottom-32 left-1/4 w-96 h-96 bg-blue-600 rounded-full mix-blend-screen filter blur-[100px] opacity-20" />
        
        <div className="relative z-10 p-10 lg:p-14">
          <div className="mb-12">
            <img src="/logoNutrixa.png" alt="Nutrixa" className="h-10 opacity-100 brightness-0 invert drop-shadow-md" />
          </div>

          <h1 className="text-4xl lg:text-5xl font-extrabold tracking-tight text-white mb-6 leading-tight">
            Prioriza tu bienestar hoy.
          </h1>
          <p className="text-lg text-zinc-300 leading-relaxed font-light max-w-md">
            Agenda tu consulta con {nutritionist.full_name} y da el primer paso hacia un estilo de vida m├ís saludable y equilibrado.
          </p>
        </div>

        <div className="relative z-10 p-10 lg:p-14 mt-auto">
          <div className="flex items-center gap-4 bg-white/5 p-4 rounded-3xl backdrop-blur-md border border-white/10 w-fit">
             <div className="bg-white/10 p-3 rounded-2xl">
               <CalendarIcon className="h-6 w-6 text-white" />
             </div>
             <div>
               <p className="text-sm font-bold text-white tracking-wide">Turnera Oficial Segura</p>
               <p className="text-xs font-medium text-zinc-400">Certificada por Nutrixa</p>
             </div>
          </div>
        </div>
      </div>

      {/* Right Panel - Booking Flow */}
      <div className="flex-1 flex flex-col min-h-screen overflow-y-auto px-4 py-8 sm:px-6 lg:px-12 bg-white relative">
        <div className="w-full max-w-2xl mx-auto my-auto space-y-8 lg:py-12">
          
          <div className="lg:hidden flex justify-center mb-8">
            <img src="/logoNutrixa.png" alt="Nutrixa" className="h-10 opacity-80" />
          </div>
          
          <div className="text-center sm:text-left space-y-3 mb-12">
            {step === 'datetime' && (
              <Button variant="ghost" className="text-zinc-500 mb-6 -ml-4 hover:bg-zinc-100 hover:text-zinc-900 rounded-xl font-bold" onClick={() => setStep('service')}>
                <ChevronLeft className="h-5 w-5 mr-1" />
                Volver a servicios
              </Button>
            )}
            <h1 className="text-3xl sm:text-4xl font-extrabold text-zinc-900 tracking-tight">
              {step === 'service' ? 'Reserva tu turno' : 'Elige tu horario'}
            </h1>
            <h2 className="text-xl font-bold text-emerald-600 sm:hidden tracking-tight">{nutritionist.full_name}</h2>
            <p className="text-zinc-500 font-medium text-base sm:text-lg mt-2">
              {step === 'service' 
                ? 'Selecciona el tipo de servicio que precisas realizar.' 
                : 'Escoge el d├¡a y la hora para confirmar tu reserva.'}
            </p>
          </div>

          {step === 'service' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {!hasServices && (
                <div className="col-span-full text-center py-16 px-4 rounded-3xl border-2 border-dashed border-zinc-200 bg-zinc-50/50">
                   <h3 className="text-xl font-black text-zinc-900 mb-2 tracking-tight">Cat├ílogo vac├¡o</h3>
                   <p className="text-sm font-medium text-zinc-500 max-w-sm mx-auto">
                     Este profesional todav├¡a no ha configurado sus servicios disponibles.
                   </p>
                </div>
              )}
              {hasServices && nutritionist.services.map((service) => (
                <Card 
                  key={service.id} 
                  className="cursor-pointer hover:shadow-[0_8px_30px_rgb(0,0,0,0.06)] transition-all duration-300 border-zinc-200 hover:border-emerald-400 hover:-translate-y-1 active:scale-[0.98] group overflow-hidden bg-white rounded-3xl"
                  onClick={() => selectService(service)}
                >
                  <div className="p-6 flex flex-row items-center justify-between gap-4">
                    <div className="flex-1 min-w-0 space-y-1">
                      <h3 className="text-lg font-bold text-zinc-900 group-hover:text-emerald-700 transition-colors truncate tracking-tight">
                        {service.name}
                      </h3>
                      <div className="flex items-center gap-1.5 text-sm font-medium text-zinc-500">
                        <Clock className="h-4 w-4 opacity-60" /> 
                        <span>{service.duration} min</span>
                      </div>
                    </div>
                    <div className="shrink-0 bg-emerald-50 px-3 py-1.5 rounded-xl border border-emerald-100 shadow-sm group-hover:bg-emerald-600 transition-colors duration-300">
                      <span className="text-base font-black text-emerald-700 group-hover:text-white tracking-tight">
                        ${service.price.toLocaleString()}
                      </span>
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          ) : (
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 lg:gap-12 items-start">
              
              <div className="space-y-6">
                {/* Selected Service Snippet */}
                <div className="bg-zinc-50 border border-zinc-200 rounded-3xl p-6 shadow-inner">
                  <p className="text-xs uppercase font-black tracking-widest text-zinc-400 mb-2">Has seleccionado</p>
                  <p className="font-extrabold text-xl text-zinc-900 tracking-tight">{selectedService?.name}</p>
                  <p className="text-sm font-bold text-emerald-700 mt-1">{selectedService?.duration} minutos de duraci├│n</p>
                </div>

                <Card className="border-zinc-200 shadow-sm rounded-3xl overflow-hidden bg-white">
                  <CardContent className="p-4 sm:p-6 flex justify-center">
                    <Calendar
                      mode="single"
                      selected={selectedDate}
                      onSelect={setSelectedDate}
                      locale={es}
                      disabled={(date) => {
                        const day = date.getDay() === 0 ? 7 : date.getDay();
                        return isBefore(date, startOfToday()) || !nutritionist.working_days?.includes(day);
                      }}
                      className="border-0"
                    />
                  </CardContent>
                </Card>
              </div>

              {/* Time & Form Selection */}
              <div className="space-y-6">
                <Card className="border-zinc-200 shadow-sm rounded-3xl overflow-hidden bg-white hover:shadow-md transition-shadow duration-300">
                  <CardHeader className="bg-zinc-50/80 border-b border-zinc-100 pb-5 pt-6">
                    <CardTitle className="text-lg font-bold flex items-center gap-2 text-zinc-900 tracking-tight">
                      <Clock className="h-5 w-5 text-emerald-600" />
                      Horarios disponibles
                    </CardTitle>
                    <CardDescription className="font-medium text-zinc-500">
                      {selectedDate 
                        ? format(selectedDate, "EEEE d 'de' MMMM", { locale: es }) 
                        : 'Selecciona una fecha en el calendario'}
                    </CardDescription>
                  </CardHeader>
                  <CardContent className="pt-6 pb-6">
                    {!selectedDate ? (
                      <div className="py-12 bg-white rounded-2xl flex flex-col items-center justify-center text-center px-4">
                        <CalendarIcon className="h-10 w-10 text-zinc-200 mb-3" />
                         <p className="text-sm font-bold text-zinc-400">Espera de fecha</p>
                      </div>
                    ) : loadingSlots ? (
                      <div className="py-12 flex flex-col items-center justify-center gap-3">
                        <Loader2 className="h-6 w-6 animate-spin text-emerald-600" />
                        <p className="text-xs font-bold text-zinc-400 uppercase tracking-widest">Buscando...</p>
                      </div>
                    ) : availableSlots.length === 0 ? (
                      <div className="py-12 text-center text-zinc-500 font-bold bg-zinc-50 rounded-2xl">
                        No hay turnos para esta fecha.
                      </div>
                    ) : (
                      <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                        {availableSlots.map((time) => (
                          <Button
                            key={time}
                            variant={selectedTime === time ? 'default' : 'outline'}
                            className={`h-12 text-sm font-bold rounded-xl transition-all duration-300 ${selectedTime === time ? 'bg-emerald-600 hover:bg-emerald-700 text-white shadow-md hover:-translate-y-0.5' : 'border-zinc-200 text-zinc-600 hover:border-emerald-300 hover:text-emerald-700 hover:bg-emerald-50'}`}
                            onClick={() => setSelectedTime(time)}
                          >
                            {time}
                          </Button>
                        ))}
                      </div>
                    )}
                  </CardContent>
                </Card>

                {/* Guest Details Form */}
                {selectedTime && (
                  <Card className="animate-in fade-in slide-in-from-bottom-4 border-zinc-200 shadow-[0_8px_30px_rgb(0,0,0,0.06)] rounded-3xl overflow-hidden bg-white">
                    <CardHeader className="bg-emerald-50/50 border-b border-emerald-100 pb-5 pt-6">
                       <CardTitle className="text-lg font-bold text-zinc-900 tracking-tight">Confirmaci├│n de Reserva</CardTitle>
                       <CardDescription className="font-medium text-emerald-700">Completa y env├¡a la solicitud para este turno</CardDescription>
                    </CardHeader>
                    <CardContent className="pt-6 pb-8">
                      <form onSubmit={handleBook} className="space-y-5">
                        <div className="space-y-2">
                          <Label htmlFor="name" className="text-sm font-bold text-zinc-700">Nombre Completo</Label>
                          <Input
                            id="name"
                            required
                            placeholder="Ej. Juan P├®rez"
                            value={guestInfo.name}
                            onChange={(e) => setGuestInfo({ ...guestInfo, name: e.target.value })}
                            className="bg-zinc-50 h-14 border-zinc-200 focus:ring-emerald-600 focus:border-emerald-600 rounded-xl shadow-sm text-base"
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="email" className="text-sm font-bold text-zinc-700">Correo Electr├│nico</Label>
                          <Input
                            id="email"
                            type="email"
                            required
                            placeholder="tu@email.com"
                            value={guestInfo.email}
                            onChange={(e) => setGuestInfo({ ...guestInfo, email: e.target.value })}
                            className="bg-zinc-50 h-14 border-zinc-200 focus:ring-emerald-600 focus:border-emerald-600 rounded-xl shadow-sm text-base"
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="phone" className="text-sm font-bold text-zinc-700">N├║mero de WhatsApp</Label>
                          <Input
                            id="phone"
                            type="tel"
                            required
                            placeholder="+54 11 1234-5678"
                            value={guestInfo.phone}
                            onChange={(e) => setGuestInfo({ ...guestInfo, phone: e.target.value })}
                            className="bg-zinc-50 h-14 border-zinc-200 focus:ring-emerald-600 focus:border-emerald-600 rounded-xl shadow-sm text-base"
                          />
                        </div>
                        <Button type="submit" className="w-full bg-emerald-600 hover:bg-emerald-700 mt-6 h-14 text-base font-bold rounded-xl transition-all shadow-md hover:-translate-y-0.5 hover:shadow-lg" disabled={booking}>
                          {booking ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : null}
                          Enviar Solicitud
                        </Button>
                      </form>
                    </CardContent>
                  </Card>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAuthStore } from '@/stores/authStore';
import { useRecipeStore } from '@/stores/recipeStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { ArrowLeft, Loader2, Plus, Save, Trash2, X } from 'lucide-react';
import type { RecipeFormData, RecipeIngredient, RecipeTag } from '@/types';

const recipeTags: { value: RecipeTag; label: string }[] = [
  { value: 'vegan', label: 'Vegano' },
  { value: 'vegetarian', label: 'Vegetariano' },
  { value: 'gluten-free', label: 'Sin Gluten' },
  { value: 'dairy-free', label: 'Sin L├ícteos' },
  { value: 'keto', label: 'Keto' },
  { value: 'low-carb', label: 'Bajo en Carbohidratos' },
  { value: 'high-protein', label: 'Alto en Prote├¡nas' },
  { value: 'breakfast', label: 'Desayuno' },
  { value: 'lunch', label: 'Almuerzo' },
  { value: 'dinner', label: 'Cena' },
  { value: 'snack', label: 'Snack' },
  { value: 'dessert', label: 'Postre' },
];

const emptyIngredient: RecipeIngredient = {
  id: '',
  name: '',
  quantity: 0,
  unit: 'g',
  calories: 0,
  protein: 0,
  carbs: 0,
  fats: 0,
};

const initialFormData: RecipeFormData = {
  name: '',
  description: '',
  ingredients: [],
  instructions: [''],
  prep_time: '',
  cook_time: '',
  servings: '1',
  calories_per_serving: '',
  tags: [],
};

export function RecipeForm() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const { user } = useAuthStore();
  const { selectedRecipe, createRecipe, updateRecipe, getRecipeById, loading } = useRecipeStore();
  
  const isEditing = Boolean(id);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState<RecipeFormData>(initialFormData);

  useEffect(() => {
    if (isEditing && id) {
      getRecipeById(id);
    }
  }, [id, isEditing]);

  useEffect(() => {
    if (isEditing && selectedRecipe) {
      setFormData({
        name: selectedRecipe.name,
        description: selectedRecipe.description || '',
        ingredients: selectedRecipe.ingredients,
        instructions: selectedRecipe.instructions.length > 0 ? selectedRecipe.instructions : [''],
        prep_time: selectedRecipe.prep_time.toString(),
        cook_time: selectedRecipe.cook_time.toString(),
        servings: selectedRecipe.servings.toString(),
        calories_per_serving: selectedRecipe.calories_per_serving.toString(),
        tags: selectedRecipe.tags,
      });
    }
  }, [selectedRecipe, isEditing]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    setSaving(true);
    
    try {
      // Clean up data
      const cleanedData = {
        ...formData,
        instructions: formData.instructions.filter(i => i.trim() !== ''),
        ingredients: formData.ingredients.map(ing => ({
          ...ing,
          id: ing.id || crypto.randomUUID(),
        })),
      };

      if (isEditing && id) {
        await updateRecipe(id, cleanedData);
      } else {
        await createRecipe(user.id, cleanedData);
      }
      navigate('/recipes');
    } catch (error) {
      console.error('Error saving recipe:', error);
    } finally {
      setSaving(false);
    }
  };

  const handleChange = (field: keyof RecipeFormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const addIngredient = () => {
    setFormData(prev => ({
      ...prev,
      ingredients: [...prev.ingredients, { ...emptyIngredient, id: crypto.randomUUID() }],
    }));
  };

  const updateIngredient = (index: number, field: keyof RecipeIngredient, value: any) => {
    setFormData(prev => {
      const newIngredients = [...prev.ingredients];
      newIngredients[index] = { ...newIngredients[index], [field]: value };
      return { ...prev, ingredients: newIngredients };
    });
  };

  const removeIngredient = (index: number) => {
    setFormData(prev => ({
      ...prev,
      ingredients: prev.ingredients.filter((_, i) => i !== index),
    }));
  };

  const addInstruction = () => {
    setFormData(prev => ({
      ...prev,
      instructions: [...prev.instructions, ''],
    }));
  };

  const updateInstruction = (index: number, value: string) => {
    setFormData(prev => {
      const newInstructions = [...prev.instructions];
      newInstructions[index] = value;
      return { ...prev, instructions: newInstructions };
    });
  };

  const removeInstruction = (index: number) => {
    setFormData(prev => ({
      ...prev,
      instructions: prev.instructions.filter((_, i) => i !== index),
    }));
  };

  const toggleTag = (tag: RecipeTag) => {
    setFormData(prev => ({
      ...prev,
      tags: prev.tags.includes(tag)
        ? prev.tags.filter(t => t !== tag)
        : [...prev.tags, tag],
    }));
  };

  // Calculate total calories from ingredients
  const totalCalories = formData.ingredients.reduce((sum, ing) => sum + (ing.calories || 0), 0);
  const servings = parseInt(formData.servings) || 1;
  const calculatedCaloriesPerServing = Math.round(totalCalories / servings);

  if (isEditing && loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => navigate('/recipes')}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-3xl font-bold text-gray-900">
            {isEditing ? 'Editar Receta' : 'Nueva Receta'}
          </h1>
          <p className="text-gray-500 mt-1">
            {isEditing 
              ? 'Actualiza los datos de la receta' 
              : 'Completa los datos para crear una nueva receta'}
          </p>
        </div>
      </div>

      <form onSubmit={handleSubmit}>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Basic Info */}
            <Card>
              <CardHeader>
                <CardTitle className="text-lg font-semibold">Informaci├│n B├ísica</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="name">Nombre de la receta *</Label>
                  <Input
                    id="name"
                    value={formData.name}
                    onChange={(e) => handleChange('name', e.target.value)}
                    required
                    placeholder="Ej: Ensalada de quinoa con verduras"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="description">Descripci├│n</Label>
                  <Textarea
                    id="description"
                    value={formData.description}
                    onChange={(e) => handleChange('description', e.target.value)}
                    placeholder="Breve descripci├│n de la receta..."
                    rows={3}
                  />
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="prep_time">Tiempo prep. (min)</Label>
                    <Input
                      id="prep_time"
                      type="number"
                      value={formData.prep_time}
                      onChange={(e) => handleChange('prep_time', e.target.value)}
                      placeholder="15"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="cook_time">Tiempo cocci├│n (min)</Label>
                    <Input
                      id="cook_time"
                      type="number"
                      value={formData.cook_time}
                      onChange={(e) => handleChange('cook_time', e.target.value)}
                      placeholder="20"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="servings">Porciones</Label>
                    <Input
                      id="servings"
                      type="number"
                      value={formData.servings}
                      onChange={(e) => handleChange('servings', e.target.value)}
                      placeholder="4"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="calories">Calor├¡as/porci├│n</Label>
                    <Input
                      id="calories"
                      type="number"
                      value={formData.calories_per_serving}
                      onChange={(e) => handleChange('calories_per_serving', e.target.value)}
                      placeholder={calculatedCaloriesPerServing > 0 ? calculatedCaloriesPerServing.toString() : '300'}
                    />
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Ingredients */}
            <Card>
              <CardHeader className="flex flex-row items-center justify-between">
                <CardTitle className="text-lg font-semibold">Ingredientes</CardTitle>
                <Button type="button" variant="outline" size="sm" onClick={addIngredient}>
                  <Plus className="h-4 w-4 mr-2" />
                  Agregar
                </Button>
              </CardHeader>
              <CardContent>
                {formData.ingredients.length === 0 ? (
                  <div className="text-center py-8 text-gray-500">
                    <p>No hay ingredientes agregados</p>
                    <Button type="button" variant="outline" className="mt-4" onClick={addIngredient}>
                      <Plus className="h-4 w-4 mr-2" />
                      Agregar ingrediente
                    </Button>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {formData.ingredients.map((ingredient, index) => (
                      <div key={index} className="flex gap-2 items-start p-4 bg-gray-50 rounded-lg">
                        <div className="flex-1 grid grid-cols-6 gap-2">
                          <div className="col-span-2">
                            <Input
                              placeholder="Nombre"
                              value={ingredient.name}
                              onChange={(e) => updateIngredient(index, 'name', e.target.value)}
                            />
                          </div>
                          <div>
                            <Input
                              type="number"
                              step="0.1"
                              placeholder="Cant."
                              value={ingredient.quantity || ''}
                              onChange={(e) => updateIngredient(index, 'quantity', parseFloat(e.target.value) || 0)}
                            />
                          </div>
                          <div>
                            <Input
                              placeholder="Unidad"
                              value={ingredient.unit}
                              onChange={(e) => updateIngredient(index, 'unit', e.target.value)}
                            />
                          </div>
                          <div>
                            <Input
                              type="number"
                              placeholder="Kcal"
                              value={ingredient.calories || ''}
                              onChange={(e) => updateIngredient(index, 'calories', parseFloat(e.target.value) || 0)}
                            />
                          </div>
                          <div className="flex gap-1">
                            <Input
                              type="number"
                              step="0.1"
                              placeholder="P"
                              value={ingredient.protein || ''}
                              onChange={(e) => updateIngredient(index, 'protein', parseFloat(e.target.value) || 0)}
                            />
                          </div>
                        </div>
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          onClick={() => removeIngredient(index)}
                          className="text-red-500"
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Instructions */}
            <Card>
              <CardHeader className="flex flex-row items-center justify-between">
                <CardTitle className="text-lg font-semibold">Preparaci├│n</CardTitle>
                <Button type="button" variant="outline" size="sm" onClick={addInstruction}>
                  <Plus className="h-4 w-4 mr-2" />
                  Agregar paso
                </Button>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {formData.instructions.map((instruction, index) => (
                    <div key={index} className="flex gap-2 items-start">
                      <span className="w-8 h-8 flex items-center justify-center bg-black text-white rounded-full text-sm font-medium shrink-0">
                        {index + 1}
                      </span>
                      <Textarea
                        value={instruction}
                        onChange={(e) => updateInstruction(index, e.target.value)}
                        placeholder={`Paso ${index + 1}...`}
                        className="flex-1 min-h-[60px]"
                      />
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        onClick={() => removeInstruction(index)}
                        className="text-red-500"
                        disabled={formData.instructions.length === 1}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Tags */}
            <Card>
              <CardHeader>
                <CardTitle className="text-lg font-semibold">Etiquetas</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex flex-wrap gap-2">
                  {recipeTags.map((tag) => (
                    <button
                      key={tag.value}
                      type="button"
                      onClick={() => toggleTag(tag.value)}
                      className={`px-3 py-1.5 rounded-full text-sm font-medium transition-all ${
                        formData.tags.includes(tag.value)
                          ? 'bg-black text-white'
                          : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                      }`}
                    >
                      {tag.label}
                    </button>
                  ))}
                </div>
              </CardContent>
            </Card>

            {/* Nutrition Summary */}
            <Card>
              <CardHeader>
                <CardTitle className="text-lg font-semibold">Resumen Nutricional</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  <div className="flex justify-between">
                    <span className="text-gray-500">Calor├¡as totales</span>
                    <span className="font-medium">{totalCalories} kcal</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-500">Por porci├│n</span>
                    <span className="font-medium">{calculatedCaloriesPerServing} kcal</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-500">Prote├¡nas totales</span>
                    <span className="font-medium">
                      {formData.ingredients.reduce((sum, ing) => sum + (ing.protein || 0), 0).toFixed(1)}g
                    </span>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Actions */}
            <div className="flex flex-col gap-3">
              <Button
                type="submit"
                className="w-full bg-black hover:bg-gray-800"
                disabled={saving}
              >
                {saving ? (
                  <Loader2 className="h-4 w-4 animate-spin mr-2" />
                ) : (
                  <Save className="h-4 w-4 mr-2" />
                )}
                {isEditing ? 'Guardar cambios' : 'Crear receta'}
              </Button>
              <Button
                type="button"
                variant="outline"
                className="w-full"
                onClick={() => navigate('/recipes')}
              >
                Cancelar
              </Button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
}

