import { create } from 'zustand';
import { supabase } from '@/lib/supabase/client';
import type { Anamnesis, AnamnesisFormData } from '@/types';
import { calculateBMI } from '@/utils/calculations';

interface AnamnesisState {
  anamnesisList: Anamnesis[];
  selectedAnamnesis: Anamnesis | null;
  loading: boolean;
  error: string | null;
  
  // Actions
  setAnamnesisList: (list: Anamnesis[]) => void;
  setSelectedAnamnesis: (anamnesis: Anamnesis | null) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  
  // CRUD Operations
  fetchAnamnesisByPatient: (patientId: string) => Promise<void>;
  getAnamnesisById: (id: string) => Promise<Anamnesis | null>;
  createAnamnesis: (userId: string, patientId: string, data: AnamnesisFormData) => Promise<{ data: Anamnesis | null; error: string | null }>;
  updateAnamnesis: (id: string, data: Partial<AnamnesisFormData>) => Promise<{ error: string | null }>;
  deleteAnamnesis: (id: string) => Promise<{ error: string | null }>;
  
  // Check if patient has anamnesis
  hasAnamnesis: (patientId: string) => boolean;
}

export const useAnamnesisStore = create<AnamnesisState>((set, get) => ({
  anamnesisList: [],
  selectedAnamnesis: null,
  loading: false,
  error: null,

  setAnamnesisList: (list) => set({ anamnesisList: list }),
  setSelectedAnamnesis: (anamnesis) => set({ selectedAnamnesis: anamnesis }),
  setLoading: (loading) => set({ loading }),
  setError: (error) => set({ error }),

  fetchAnamnesisByPatient: async (patientId) => {
    set({ loading: true, error: null });
    try {
      const { data, error } = await supabase
        .from('anamnesis')
        .select('*')
        .eq('patient_id', patientId)
        .order('created_at', { ascending: false });

      if (error) {
        set({ error: error.message, loading: false });
        return;
      }

      set({ anamnesisList: data as Anamnesis[] || [], loading: false });
    } catch (err: any) {
      set({ error: err.message, loading: false });
    }
  },

  getAnamnesisById: async (id) => {
    try {
      const { data, error } = await supabase
        .from('anamnesis')
        .select('*')
        .eq('id', id)
        .single();

      if (error) {
        set({ error: error.message });
        return null;
      }

      set({ selectedAnamnesis: data as Anamnesis });
      return data as Anamnesis;
    } catch (err: any) {
      set({ error: err.message });
      return null;
    }
  },

  createAnamnesis: async (userId, patientId, data) => {
    set({ loading: true, error: null });
    try {
      // Calculate BMI
      const weight = parseFloat(data.anthropometric_data.weight) || 0;
      const height = parseFloat(data.anthropometric_data.height) || 0;
      const bmi = calculateBMI(weight, height);

      const anamnesisData = {
        patient_id: patientId,
        user_id: userId,
        physical_activity: data.physical_activity.level ? {
          level: data.physical_activity.level,
          activities: data.physical_activity.activities,
          frequency: data.physical_activity.frequency,
          duration: data.physical_activity.duration,
        } : null,
        consultation_reason: data.consultation_reason,
        anthropometric_data: {
          weight,
          height,
          bmi,
          waist_circumference: parseFloat(data.anthropometric_data.waist_circumference) || null,
          hip_circumference: parseFloat(data.anthropometric_data.hip_circumference) || null,
          arm_circumference: parseFloat(data.anthropometric_data.arm_circumference) || null,
          body_fat_percentage: parseFloat(data.anthropometric_data.body_fat_percentage) || null,
          muscle_mass: parseFloat(data.anthropometric_data.muscle_mass) || null,
        },
        diseases: data.diseases,
        medications: data.medications.filter(m => m.name.trim() !== ''),
        family_history: data.family_history.filter(fh => fh.condition.trim() !== ''),
        eating_habits: {
          meal_frequency: parseInt(data.eating_habits.meal_frequency) || 3,
          meal_times: data.eating_habits.meal_times,
          cooking_methods: data.eating_habits.cooking_methods,
          food_preferences: data.eating_habits.food_preferences,
          food_dislikes: data.eating_habits.food_dislikes,
          allergies: data.eating_habits.allergies,
          intolerances: data.eating_habits.intolerances,
        },
        recall_24h: data.recall_24h,
        lab_results: data.lab_results.filter(lr => lr.test_name.trim() !== ''),
      };

      const { data: newAnamnesis, error } = await supabase
        .from('anamnesis')
        .insert(anamnesisData)
        .select()
        .single();

      if (error) {
        set({ error: error.message, loading: false });
        return { data: null, error: error.message };
      }

      set(state => ({ 
        anamnesisList: [newAnamnesis as Anamnesis, ...state.anamnesisList],
        loading: false 
      }));

      return { data: newAnamnesis as Anamnesis, error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { data: null, error: err.message };
    }
  },

  updateAnamnesis: async (id, data) => {
    set({ loading: true, error: null });
    try {
      const updateData: any = {};

      if (data.physical_activity) {
        updateData.physical_activity = data.physical_activity.level ? {
          level: data.physical_activity.level,
          activities: data.physical_activity.activities,
          frequency: data.physical_activity.frequency,
          duration: data.physical_activity.duration,
        } : null;
      }

      if (data.consultation_reason) {
        updateData.consultation_reason = data.consultation_reason;
      }

      if (data.anthropometric_data) {
        const weight = parseFloat(data.anthropometric_data.weight) || 0;
        const height = parseFloat(data.anthropometric_data.height) || 0;
        updateData.anthropometric_data = {
          weight,
          height,
          bmi: calculateBMI(weight, height),
          waist_circumference: parseFloat(data.anthropometric_data.waist_circumference) || null,
          hip_circumference: parseFloat(data.anthropometric_data.hip_circumference) || null,
          arm_circumference: parseFloat(data.anthropometric_data.arm_circumference) || null,
          body_fat_percentage: parseFloat(data.anthropometric_data.body_fat_percentage) || null,
          muscle_mass: parseFloat(data.anthropometric_data.muscle_mass) || null,
        };
      }

      if (data.diseases) updateData.diseases = data.diseases;
      if (data.medications) updateData.medications = data.medications.filter(m => m.name.trim() !== '');
      if (data.family_history) updateData.family_history = data.family_history.filter(fh => fh.condition.trim() !== '');
      if (data.eating_habits) updateData.eating_habits = data.eating_habits;
      if (data.recall_24h) updateData.recall_24h = data.recall_24h;
      if (data.lab_results) updateData.lab_results = data.lab_results.filter(lr => lr.test_name.trim() !== '');

      const { error } = await supabase
        .from('anamnesis')
        .update(updateData)
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      // Update local state
      set(state => ({
        anamnesisList: state.anamnesisList.map(a => 
          a.id === id ? { ...a, ...updateData } as Anamnesis : a
        ),
        selectedAnamnesis: state.selectedAnamnesis?.id === id 
          ? { ...state.selectedAnamnesis, ...updateData } as Anamnesis
          : state.selectedAnamnesis,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  deleteAnamnesis: async (id) => {
    set({ loading: true, error: null });
    try {
      const { error } = await supabase
        .from('anamnesis')
        .delete()
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      set(state => ({
        anamnesisList: state.anamnesisList.filter(a => a.id !== id),
        selectedAnamnesis: state.selectedAnamnesis?.id === id ? null : state.selectedAnamnesis,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  hasAnamnesis: (patientId) => {
    const { anamnesisList } = get();
    return anamnesisList.some(a => a.patient_id === patientId);
  },
}));

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { supabase } from '@/lib/supabase/client';
import type { User } from '@/types';

let isInitialized = false;

interface AuthState {
  user: User | null;
  session: any | null;
  loading: boolean;
  error: string | null;
  
  // Actions
  setUser: (user: User | null) => void;
  setSession: (session: any | null) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  
  // Auth methods
  signIn: (email: string, password: string) => Promise<{ error: string | null }>;
  signUp: (email: string, password: string, fullName: string) => Promise<{ error: string | null }>;
  signOut: () => Promise<void>;
  resetPassword: (email: string) => Promise<{ error: string | null }>;
  updateProfile: (data: Partial<User>) => Promise<{ error: string | null }>;
  
  // Initialize
  initializeAuth: () => Promise<void>;
}

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      user: null,
      session: null,
      loading: true,
      error: null,

      setUser: (user) => set({ user }),
      setSession: (session) => set({ session }),
      setLoading: (loading) => set({ loading }),
      setError: (error) => set({ error }),

      signIn: async (email, password) => {
        set({ loading: true, error: null });
        try {
          const { data, error } = await supabase.auth.signInWithPassword({
            email,
            password,
          });

          if (error) {
            set({ error: error.message, loading: false });
            return { error: error.message };
          }

          // Fetch user profile
          let { data: profile, error: profileError } = await supabase
            .from('users')
            .select('*')
            .eq('id', data.user.id)
            .single();

          // Si el perfil no existe, intentamos crearlo
          if (profileError || !profile) {
            const { data: newProfile, error: createError } = await supabase
              .from('users')
              .insert({
                id: data.user.id,
                email: data.user.email,
                full_name: data.user.user_metadata?.full_name || 'Usuario',
                role: 'nutritionist',
              } as any)
              .select()
              .single();
            
            if (!createError && newProfile) {
              profile = newProfile;
            } else if (createError) {
              set({ error: createError.message, loading: false });
              return { error: createError.message };
            }
          }

          if (profile) {
            set({ 
              user: profile as unknown as User, 
              session: data.session, 
              loading: false 
            });
            return { error: null };
          } else {
            set({ error: 'No se pudo cargar o crear el perfil de usuario', loading: false });
            return { error: 'Perfil no encontrado' };
          }
        } catch (err: any) {
          set({ error: err.message, loading: false });
          return { error: err.message };
        }
      },

      signUp: async (email, password, fullName) => {
        set({ loading: true, error: null });
        try {
          const { data, error } = await supabase.auth.signUp({
            email,
            password,
            options: {
              data: {
                full_name: fullName,
              },
            },
          });

          if (error) {
            set({ error: error.message, loading: false });
            return { error: error.message };
          }

          if (data.user) {
            set({ loading: false });
            return { error: null };
          }

          set({ loading: false });
          return { error: null };
        } catch (err: any) {
          set({ error: err.message, loading: false });
          return { error: err.message };
        }
      },

      signOut: async () => {
        set({ loading: true });
        try {
          await supabase.auth.signOut();
        } catch (err) {
          console.error('Error signing out:', err);
        } finally {
          set({ user: null, session: null, loading: false, error: null });
        }
      },

      resetPassword: async (email) => {
        set({ loading: true, error: null });
        try {
          const { error } = await supabase.auth.resetPasswordForEmail(email, {
            redirectTo: `${window.location.origin}/reset-password`,
          });

          if (error) {
            set({ error: error.message, loading: false });
            return { error: error.message };
          }

          set({ loading: false });
          return { error: null };
        } catch (err: any) {
          set({ error: err.message, loading: false });
          return { error: err.message };
        }
      },

      updateProfile: async (data: Partial<User>) => {
        set({ error: null });
        console.log('[AuthStore] Iniciando updateProfile con datos:', data);
        try {
          const { user, session } = get();
          if (!user) {
            console.error('[AuthStore] Error: No hay usuario autenticado');
            return { error: 'No hay usuario autenticado' };
          }

          console.log('[AuthStore] Ejecutando update en Supabase para id:', user.id);
          
          // Limpiamos los datos para evitar circular references
          const pureData = JSON.parse(JSON.stringify(data));
          
          // FORZAMOS UN FETCH NATIVO (BYPASS AL CLIENTE SUPABASE DE JS) 
          // Esto evita ABSOLUTAMENTE cualquier cuelgue interno, lockeos de sesi├│n o bugs del SDK con arrays JSONB
          const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
          const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
          
          const controller = new AbortController();
          const timeoutId = setTimeout(() => controller.abort(), 10000);

          try {
            const token = session?.access_token;
            if (!token) throw new Error('No hay token de sesi├│n v├ílido');

            const response = await fetch(`${supabaseUrl}/rest/v1/users?id=eq.${user.id}`, {
              method: 'PATCH',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`,
                'apikey': supabaseKey,
                'Prefer': 'return=minimal'
              },
              body: JSON.stringify(pureData),
              signal: controller.signal
            });

            clearTimeout(timeoutId);

            if (!response.ok) {
              const errBody = await response.text();
              console.error('[AuthStore] Error de REST Supabase:', errBody);
              set({ error: errBody });
              return { error: 'Error del servidor: ' + errBody };
            }
            
            console.log('[AuthStore] Respuesta de Update REST exitosa');
            
          } catch (fetchError: any) {
            clearTimeout(timeoutId);
            if (fetchError.name === 'AbortError') {
              console.warn('[AuthStore] REST Fetch abortado por lentitud de red.');
              return { error: 'La red tard├│ m├ís de 10 segundos en responder. Comprueba tu internet.' };
            }
            throw fetchError;
          }

          // Actualizamos el estado local de inmediato con los datos que mandamos
          const updatedUser = { ...user, ...pureData };
          set({ user: updatedUser });
          
          console.log('[AuthStore] Store local actualizado con ├®xito tras guardado');
          return { error: null };
        } catch (err: any) {
          console.error('[AuthStore] Excepci├│n cr├¡tica en updateProfile:', err);
          set({ error: err.message });
          return { error: err.message };
        }
      },

      initializeAuth: async () => {
        if (isInitialized) return;
        isInitialized = true;

        try {
          const { data: { session } } = await supabase.auth.getSession();
          
          if (session?.user) {
            // Fetch user profile
            let { data: profile, error } = await supabase
              .from('users')
              .select('*')
              .eq('id', session.user.id)
              .single();

            // Si falta el perfil al inicializar, lo creamos
            if (error || !profile) {
              const { data: newProfile, error: createError } = await supabase
                .from('users')
                .insert({
                  id: session.user.id,
                  email: session.user.email,
                  full_name: session.user.user_metadata?.full_name || 'Usuario',
                  role: 'nutritionist',
                } as any)
                .select()
                .single();
              
              if (!createError && newProfile) {
                profile = newProfile;
              }
            }

            if (profile) {
              set({ 
                user: profile as unknown as User, 
                session,
                loading: false 
              });
            } else {
              set({ loading: false });
            }
          } else {
            set({ loading: false });
          }

          // Listen for auth changes
          supabase.auth.onAuthStateChange(async (_event, session) => {
            if (session?.user) {
              let { data: profile, error } = await supabase
                .from('users')
                .select('*')
                .eq('id', session.user.id)
                .single();

              if (error || !profile) {
                const { data: newProfile, error: createError } = await supabase
                  .from('users')
                  .insert({
                    id: session.user.id,
                    email: session.user.email,
                    full_name: session.user.user_metadata?.full_name || 'Usuario',
                    role: 'nutritionist',
                  } as any)
                  .select()
                  .single();
                
                if (!createError && newProfile) {
                  profile = newProfile;
                }
              }

              set({ 
                user: (profile as unknown as User) || null, 
                session 
              });
            } else {
              set({ user: null, session: null });
            }
          });
        } catch (err) {
          set({ loading: false });
        }
      },
    }),
    {
      name: 'auth-storage',
      partialize: (state) => ({ user: state.user, session: state.session }),
    }
  )
);

import { create } from 'zustand';
import { supabase } from '@/lib/supabase/client';
import type { FollowUp, FollowUpWithPatient } from '@/types';

interface FollowUpState {
  followUps: FollowUp[];
  followUpsWithPatient: FollowUpWithPatient[];
  selectedFollowUp: FollowUp | null;
  loading: boolean;
  error: string | null;
  
  // Actions
  setFollowUps: (followUps: FollowUp[]) => void;
  setFollowUpsWithPatient: (followUps: FollowUpWithPatient[]) => void;
  setSelectedFollowUp: (followUp: FollowUp | null) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  
  // CRUD Operations
  fetchFollowUps: (userId: string) => Promise<void>;
  fetchFollowUpsByPatient: (patientId: string) => Promise<void>;
  getFollowUpById: (id: string) => Promise<FollowUp | null>;
  createFollowUp: (userId: string, patientId: string, data: {
    date: string;
    weight: number;
    notes?: string;
    adherence?: 'excellent' | 'good' | 'fair' | 'poor';
    symptoms?: string[];
    concerns?: string[];
    next_appointment?: string;
  }) => Promise<{ data: FollowUp | null; error: string | null }>;
  updateFollowUp: (id: string, data: Partial<{
    date: string;
    weight: number;
    notes: string;
    adherence: 'excellent' | 'good' | 'fair' | 'poor';
    symptoms: string[];
    concerns: string[];
    next_appointment: string;
  }>) => Promise<{ error: string | null }>;
  deleteFollowUp: (id: string) => Promise<{ error: string | null }>;
  
  // Computed
  getUpcomingAppointments: (days?: number) => FollowUp[];
  getFollowUpsByPatient: (patientId: string) => FollowUp[];
  getWeightHistory: (patientId: string) => { date: string; weight: number }[];
}

export const useFollowUpStore = create<FollowUpState>((set, get) => ({
  followUps: [],
  followUpsWithPatient: [],
  selectedFollowUp: null,
  loading: false,
  error: null,

  setFollowUps: (followUps) => set({ followUps }),
  setFollowUpsWithPatient: (followUpsWithPatient) => set({ followUpsWithPatient }),
  setSelectedFollowUp: (followUp) => set({ selectedFollowUp: followUp }),
  setLoading: (loading) => set({ loading }),
  setError: (error) => set({ error }),

  fetchFollowUps: async (userId) => {
    set({ loading: true, error: null });
    try {
      const { data, error } = await supabase
        .from('follow_ups')
        .select(`
          *,
          patient:patients(*)
        `)
        .eq('user_id', userId)
        .order('date', { ascending: false });

      if (error) {
        set({ error: error.message, loading: false });
        return;
      }

      set({ 
        followUps: data as FollowUp[] || [],
        followUpsWithPatient: data as FollowUpWithPatient[] || [],
        loading: false 
      });
    } catch (err: any) {
      set({ error: err.message, loading: false });
    }
  },

  fetchFollowUpsByPatient: async (patientId) => {
    set({ loading: true, error: null });
    try {
      const { data, error } = await supabase
        .from('follow_ups')
        .select('*')
        .eq('patient_id', patientId)
        .order('date', { ascending: false });

      if (error) {
        set({ error: error.message, loading: false });
        return;
      }

      set({ followUps: data as FollowUp[] || [], loading: false });
    } catch (err: any) {
      set({ error: err.message, loading: false });
    }
  },

  getFollowUpById: async (id) => {
    try {
      const { data, error } = await supabase
        .from('follow_ups')
        .select('*')
        .eq('id', id)
        .single();

      if (error) {
        set({ error: error.message });
        return null;
      }

      set({ selectedFollowUp: data as FollowUp });
      return data as FollowUp;
    } catch (err: any) {
      set({ error: err.message });
      return null;
    }
  },

  createFollowUp: async (userId, patientId, data) => {
    set({ loading: true, error: null });
    try {
      const followUpData = {
        patient_id: patientId,
        user_id: userId,
        date: data.date,
        weight: data.weight,
        notes: data.notes || null,
        adherence: data.adherence || null,
        symptoms: data.symptoms || [],
        concerns: data.concerns || [],
        next_appointment: data.next_appointment || null,
      };

      const { data: newFollowUp, error } = await supabase
        .from('follow_ups')
        .insert(followUpData)
        .select(`
          *,
          patient:patients(*)
        `)
        .single();

      if (error) {
        set({ error: error.message, loading: false });
        return { data: null, error: error.message };
      }

      set(state => ({ 
        followUps: [newFollowUp as FollowUp, ...state.followUps],
        followUpsWithPatient: [newFollowUp as FollowUpWithPatient, ...state.followUpsWithPatient],
        loading: false 
      }));

      return { data: newFollowUp as FollowUp, error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { data: null, error: err.message };
    }
  },

  updateFollowUp: async (id, data) => {
    set({ loading: true, error: null });
    try {
      const updateData: any = {};
      
      if (data.date) updateData.date = data.date;
      if (data.weight !== undefined) updateData.weight = data.weight;
      if (data.notes !== undefined) updateData.notes = data.notes || null;
      if (data.adherence !== undefined) updateData.adherence = data.adherence || null;
      if (data.symptoms) updateData.symptoms = data.symptoms;
      if (data.concerns) updateData.concerns = data.concerns;
      if (data.next_appointment !== undefined) updateData.next_appointment = data.next_appointment || null;

      const { error } = await supabase
        .from('follow_ups')
        .update(updateData)
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      // Fetch the updated entry to get full relations if it's needed, or just merge memory
      // The easiest way is to selectively update state mapping:
      set(state => ({
        followUps: state.followUps.map(fu => 
          fu.id === id ? { ...fu, ...updateData } as FollowUp : fu
        ),
        followUpsWithPatient: state.followUpsWithPatient.map(fu => 
          fu.id === id ? { ...fu, ...updateData } as FollowUpWithPatient : fu
        ),
        selectedFollowUp: state.selectedFollowUp?.id === id 
          ? { ...state.selectedFollowUp, ...updateData } as FollowUp
          : state.selectedFollowUp,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  deleteFollowUp: async (id) => {
    set({ loading: true, error: null });
    try {
      const { error } = await supabase
        .from('follow_ups')
        .delete()
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      set(state => ({
        followUps: state.followUps.filter(fu => fu.id !== id),
        followUpsWithPatient: state.followUpsWithPatient.filter(fu => fu.id !== id),
        selectedFollowUp: state.selectedFollowUp?.id === id ? null : state.selectedFollowUp,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  getUpcomingAppointments: (days = 7) => {
    const { followUps } = get();
    const today = new Date();
    const futureDate = new Date();
    futureDate.setDate(today.getDate() + days);

    return followUps.filter(fu => {
      if (!fu.next_appointment) return false;
      const appointmentDate = new Date(fu.next_appointment);
      return appointmentDate >= today && appointmentDate <= futureDate;
    }).sort((a, b) => {
      return new Date(a.next_appointment!).getTime() - new Date(b.next_appointment!).getTime();
    });
  },

  getFollowUpsByPatient: (patientId) => {
    const { followUps } = get();
    return followUps.filter(fu => fu.patient_id === patientId);
  },

  getWeightHistory: (patientId) => {
    const { followUps } = get();
    return followUps
      .filter(fu => fu.patient_id === patientId)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
      .map(fu => ({
        date: fu.date,
        weight: fu.weight,
      }));
  },
}));

import { create } from 'zustand';
import { supabase, supabaseRestGet } from '@/lib/supabase/client';
import type { MealPlan, MealPlanFormData, MealType } from '@/types';

interface MealPlanState {
  mealPlans: MealPlan[];
  selectedMealPlan: MealPlan | null;
  loading: boolean;
  error: string | null;
  
  // Actions
  setMealPlans: (plans: MealPlan[]) => void;
  setSelectedMealPlan: (plan: MealPlan | null) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  
  // CRUD Operations
  fetchMealPlans: (userId: string) => Promise<void>;
  fetchMealPlansByPatient: (patientId: string) => Promise<void>;
  getMealPlanById: (id: string) => Promise<MealPlan | null>;
  createMealPlan: (userId: string, patientId: string, data: MealPlanFormData) => Promise<{ data: MealPlan | null; error: string | null }>;
  updateMealPlan: (id: string, data: Partial<MealPlanFormData>) => Promise<{ error: string | null }>;
  deleteMealPlan: (id: string) => Promise<{ error: string | null }>;
  activateMealPlan: (id: string) => Promise<{ error: string | null }>;
  
  // Computed
  getActiveMealPlan: (patientId: string) => MealPlan | null;
  getMealPlansByPatient: (patientId: string) => MealPlan[];
}

const defaultDays = [
  { day_of_week: 1, meals: [] },
  { day_of_week: 2, meals: [] },
  { day_of_week: 3, meals: [] },
  { day_of_week: 4, meals: [] },
  { day_of_week: 5, meals: [] },
  { day_of_week: 6, meals: [] },
  { day_of_week: 7, meals: [] },
];

const defaultMeals: { type: MealType; name: string; time: string }[] = [
  { type: 'breakfast', name: 'Desayuno', time: '08:00' },
  { type: 'mid_morning', name: 'Media Ma├▒ana', time: '10:30' },
  { type: 'lunch', name: 'Almuerzo', time: '13:00' },
  { type: 'snack', name: 'Merienda', time: '16:30' },
  { type: 'dinner', name: 'Cena', time: '20:00' },
];

export const useMealPlanStore = create<MealPlanState>((set, get) => ({
  mealPlans: [],
  selectedMealPlan: null,
  loading: false,
  error: null,

  setMealPlans: (plans) => set({ mealPlans: plans }),
  setSelectedMealPlan: (plan) => set({ selectedMealPlan: plan }),
  setLoading: (loading) => set({ loading }),
  setError: (error) => set({ error }),

  fetchMealPlans: async (userId) => {
    set({ loading: true, error: null });
    try {
      const data = await supabaseRestGet('meal_plans', `user_id=eq.${userId}&select=*&order=created_at.desc`);
      set({ mealPlans: data as MealPlan[] || [], loading: false });
    } catch (err: any) {
      set({ error: err.message, loading: false });
    }
  },

  fetchMealPlansByPatient: async (patientId) => {
    set({ loading: true, error: null });
    try {
      const data = await supabaseRestGet('meal_plans', `patient_id=eq.${patientId}&select=*&order=created_at.desc`);
      set({ mealPlans: data as MealPlan[] || [], loading: false });
    } catch (err: any) {
      set({ error: err.message, loading: false });
    }
  },

  getMealPlanById: async (id) => {
    try {
      const { data, error } = await supabase
        .from('meal_plans')
        .select('*')
        .eq('id', id)
        .single();

      if (error) {
        set({ error: error.message });
        return null;
      }

      set({ selectedMealPlan: data as MealPlan });
      return data as MealPlan;
    } catch (err: any) {
      set({ error: err.message });
      return null;
    }
  },

  createMealPlan: async (userId, patientId, data) => {
    set({ loading: true, error: null });
    try {
      // Ensure all days have meals
      const daysWithMeals = data.days.map((day, index) => ({
        day_of_week: day.day_of_week || index + 1,
        meals: day.meals.length > 0 ? day.meals.map(meal => ({
          id: crypto.randomUUID(),
          type: meal.type,
          name: meal.name || defaultMeals.find(m => m.type === meal.type)?.name || '',
          time: meal.time || defaultMeals.find(m => m.type === meal.type)?.time || '',
          recipes: meal.recipes.map(r => ({
            recipe_id: r.recipe_id,
            recipe_name: '', // Will be populated from recipe
            quantity: parseFloat(r.quantity) || 1,
            unit: 'porci├│n',
            calories: 0,
          })),
          notes: meal.notes || null,
        })) : [],
      }));

      const mealPlanData = {
        patient_id: patientId,
        user_id: userId,
        name: data.name,
        description: data.description || null,
        start_date: data.start_date,
        end_date: data.end_date || null,
        daily_calories: parseInt(data.daily_calories) || 2000,
        macros: {
          protein: parseInt(data.macros.protein) || 30,
          carbs: parseInt(data.macros.carbs) || 40,
          fats: parseInt(data.macros.fats) || 30,
        },
        days: daysWithMeals,
        is_active: true,
      };

      const { data: newMealPlan, error } = await (supabase as any)
        .from('meal_plans')
        .insert(mealPlanData as any)
        .select()
        .single();

      if (error) {
        set({ error: error.message, loading: false });
        return { data: null, error: error.message };
      }

      set(state => ({ 
        mealPlans: [newMealPlan as MealPlan, ...state.mealPlans],
        loading: false 
      }));

      return { data: newMealPlan as MealPlan, error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { data: null, error: err.message };
    }
  },

  updateMealPlan: async (id, data) => {
    set({ loading: true, error: null });
    try {
      const updateData: any = {};

      if (data.name) updateData.name = data.name;
      if (data.description !== undefined) updateData.description = data.description || null;
      if (data.start_date) updateData.start_date = data.start_date;
      if (data.end_date !== undefined) updateData.end_date = data.end_date || null;
      if (data.daily_calories) updateData.daily_calories = parseInt(data.daily_calories);
      if (data.macros) {
        updateData.macros = {
          protein: parseInt(data.macros.protein) || 30,
          carbs: parseInt(data.macros.carbs) || 40,
          fats: parseInt(data.macros.fats) || 30,
        };
      }
      if (data.days) {
        updateData.days = data.days.map((day, index) => ({
          day_of_week: day.day_of_week || index + 1,
          meals: day.meals.map(meal => ({
            id: meal.id || crypto.randomUUID(),
            type: meal.type,
            name: meal.name,
            time: meal.time,
            recipes: meal.recipes.map(r => ({
              recipe_id: r.recipe_id,
              recipe_name: r.recipe_name || '',
              quantity: parseFloat(r.quantity as string) || r.quantity || 1,
              unit: r.unit || 'porci├│n',
              calories: r.calories || 0,
            })),
            notes: meal.notes || null,
          })),
        }));
      }

      const { error } = await (supabase as any)
        .from('meal_plans')
        .update(updateData)
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      // Update local state
      set(state => ({
        mealPlans: state.mealPlans.map(mp => 
          mp.id === id ? { ...mp, ...updateData } as MealPlan : mp
        ),
        selectedMealPlan: state.selectedMealPlan?.id === id 
          ? { ...state.selectedMealPlan, ...updateData } as MealPlan
          : state.selectedMealPlan,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  deleteMealPlan: async (id) => {
    set({ loading: true, error: null });
    try {
      const { error } = await (supabase as any)
        .from('meal_plans')
        .delete()
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      set(state => ({
        mealPlans: state.mealPlans.filter(mp => mp.id !== id),
        selectedMealPlan: state.selectedMealPlan?.id === id ? null : state.selectedMealPlan,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  activateMealPlan: async (id) => {
    set({ loading: true, error: null });
    try {
      // First, deactivate all other plans for this patient
      const plan = get().mealPlans.find(mp => mp.id === id);
      if (!plan) {
        return { error: 'Plan no encontrado' };
      }

      // Deactivate other plans
      await supabase
        .from('meal_plans')
        .update({ is_active: false })
        .eq('patient_id', plan.patient_id)
        .neq('id', id);

      // Activate this plan
      const { error } = await supabase
        .from('meal_plans')
        .update({ is_active: true })
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      // Update local state
      set(state => ({
        mealPlans: state.mealPlans.map(mp => 
          mp.patient_id === plan.patient_id 
            ? { ...mp, is_active: mp.id === id } as MealPlan
            : mp
        ),
        selectedMealPlan: state.selectedMealPlan?.id === id 
          ? { ...state.selectedMealPlan, is_active: true } as MealPlan
          : state.selectedMealPlan,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  getActiveMealPlan: (patientId) => {
    const { mealPlans } = get();
    return mealPlans.find(mp => mp.patient_id === patientId && mp.is_active) || null;
  },

  getMealPlansByPatient: (patientId) => {
    const { mealPlans } = get();
    return mealPlans.filter(mp => mp.patient_id === patientId);
  },
}));

import { create } from 'zustand';
import { supabase, supabaseRestGet } from '@/lib/supabase/client';
import type { Patient, PatientFormData, PatientWithAge } from '@/types';
import { calculateAge } from '@/utils/calculations';

interface PatientState {
  patients: PatientWithAge[];
  selectedPatient: PatientWithAge | null;
  loading: boolean;
  error: string | null;
  searchQuery: string;
  
  // Actions
  setPatients: (patients: PatientWithAge[]) => void;
  setSelectedPatient: (patient: PatientWithAge | null) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  setSearchQuery: (query: string) => void;
  
  // CRUD Operations
  fetchPatients: (userId: string) => Promise<void>;
  getPatientById: (id: string) => Promise<PatientWithAge | null>;
  createPatient: (userId: string, data: PatientFormData) => Promise<{ data: Patient | null; error: string | null }>;
  updatePatient: (id: string, data: Partial<PatientFormData>) => Promise<{ error: string | null }>;
  deletePatient: (id: string) => Promise<{ error: string | null }>;
  
  // Computed
  filteredPatients: () => PatientWithAge[];
  getRecentPatients: (limit?: number) => PatientWithAge[];
}

export const usePatientStore = create<PatientState>((set, get) => ({
  patients: [],
  selectedPatient: null,
  loading: false,
  error: null,
  searchQuery: '',

  setPatients: (patients) => set({ patients }),
  setSelectedPatient: (patient) => set({ selectedPatient: patient }),
  setLoading: (loading) => set({ loading }),
  setError: (error) => set({ error }),
  setSearchQuery: (query) => set({ searchQuery: query }),

  fetchPatients: async (userId) => {
    set({ loading: true, error: null });
    try {
      const data = await supabaseRestGet('patients', `user_id=eq.${userId}&select=*&order=created_at.desc`);

      const patientsWithAge = (data || []).map((patient: any) => ({
        ...patient,
        age: calculateAge(patient.birth_date),
      })) as PatientWithAge[];

      set({ patients: patientsWithAge, loading: false });
    } catch (err: any) {
      set({ error: err.message, loading: false });
    }
  },

  getPatientById: async (id) => {
    try {
      const { data, error } = await supabase
        .from('patients')
        .select('*')
        .eq('id', id)
        .single();

      if (error) {
        set({ error: error.message });
        return null;
      }

      const patientWithAge = {
        ...(data as any),
        age: calculateAge((data as any).birth_date),
      } as PatientWithAge;

      set({ selectedPatient: patientWithAge });
      return patientWithAge;
    } catch (err: any) {
      set({ error: err.message });
      return null;
    }
  },

  createPatient: async (userId, data) => {
    set({ loading: true, error: null });
    try {
      const patientData = {
        user_id: userId,
        first_name: data.first_name,
        last_name: data.last_name,
        email: data.email || null,
        phone: data.phone || null,
        birth_date: data.birth_date,
        gender: data.gender,
        occupation: data.occupation || null,
        work_schedule: data.work_schedule || null,
        stress_level: data.stress_level || null,
      };

      const { data: newPatient, error } = await supabase
        .from('patients')
        .insert(patientData as any)
        .select()
        .single();

      if (error) {
        set({ error: error.message, loading: false });
        return { data: null, error: error.message };
      }

      const patientWithAge = {
        ...(newPatient as any),
        age: calculateAge((newPatient as any).birth_date),
      } as PatientWithAge;

      set(state => ({ 
        patients: [patientWithAge, ...state.patients],
        loading: false 
      }));

      return { data: newPatient, error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { data: null, error: err.message };
    }
  },

  updatePatient: async (id, data) => {
    set({ loading: true, error: null });
    try {
      const updateData = {
        ...data,
        stress_level: data.stress_level || null,
      };

      const { error } = await (supabase as any)
        .from('patients')
        .update(updateData)
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      // Update local state
      set(state => ({
        patients: state.patients.map(p => 
          p.id === id ? { ...p, ...updateData, age: p.age } : p
        ),
        selectedPatient: state.selectedPatient?.id === id 
          ? { ...state.selectedPatient, ...updateData, age: state.selectedPatient.age }
          : state.selectedPatient,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  deletePatient: async (id) => {
    set({ loading: true, error: null });
    try {
      const { error } = await (supabase as any)
        .from('patients')
        .delete()
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      set(state => ({
        patients: state.patients.filter(p => p.id !== id),
        selectedPatient: state.selectedPatient?.id === id ? null : state.selectedPatient,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  filteredPatients: () => {
    const { patients, searchQuery } = get();
    if (!searchQuery.trim()) return patients;

    const query = searchQuery.toLowerCase();
    return patients.filter(patient =>
      patient.first_name.toLowerCase().includes(query) ||
      patient.last_name.toLowerCase().includes(query) ||
      patient.email?.toLowerCase().includes(query) ||
      patient.phone?.toLowerCase().includes(query)
    );
  },

  getRecentPatients: (limit = 5) => {
    const { patients } = get();
    return patients.slice(0, limit);
  },
}));

import { create } from 'zustand';
import { supabase, supabaseRestGet } from '@/lib/supabase/client';
import type { Recipe, RecipeFormData, RecipeTag } from '@/types';

interface RecipeState {
  recipes: Recipe[];
  selectedRecipe: Recipe | null;
  loading: boolean;
  error: string | null;
  searchQuery: string;
  selectedTags: RecipeTag[];
  
  // Actions
  setRecipes: (recipes: Recipe[]) => void;
  setSelectedRecipe: (recipe: Recipe | null) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  setSearchQuery: (query: string) => void;
  setSelectedTags: (tags: RecipeTag[]) => void;
  
  // CRUD Operations
  fetchRecipes: (userId: string) => Promise<void>;
  getRecipeById: (id: string) => Promise<Recipe | null>;
  createRecipe: (userId: string, data: RecipeFormData) => Promise<{ data: Recipe | null; error: string | null }>;
  updateRecipe: (id: string, data: Partial<RecipeFormData>) => Promise<{ error: string | null }>;
  deleteRecipe: (id: string) => Promise<{ error: string | null }>;
  
  // Computed
  filteredRecipes: () => Recipe[];
  getRecipesByTag: (tag: RecipeTag) => Recipe[];
  getTemplateRecipes: () => Recipe[];
}

export const useRecipeStore = create<RecipeState>((set, get) => ({
  recipes: [],
  selectedRecipe: null,
  loading: false,
  error: null,
  searchQuery: '',
  selectedTags: [],

  setRecipes: (recipes) => set({ recipes }),
  setSelectedRecipe: (recipe) => set({ selectedRecipe: recipe }),
  setLoading: (loading) => set({ loading }),
  setError: (error) => set({ error }),
  setSearchQuery: (query) => set({ searchQuery: query }),
  setSelectedTags: (tags) => set({ selectedTags: tags }),

  fetchRecipes: async (userId) => {
    set({ loading: true, error: null });
    try {
      const data = await supabaseRestGet('recipes', `select=*&or=(user_id.eq.${userId},is_template.eq.true)&order=created_at.desc`);
      set({ recipes: data || [], loading: false });
    } catch (err: any) {
      set({ error: err.message, loading: false });
    }
  },

  getRecipeById: async (id) => {
    try {
      const { data, error } = await supabase
        .from('recipes')
        .select('*')
        .eq('id', id)
        .single();

      if (error) {
        set({ error: error.message });
        return null;
      }

      set({ selectedRecipe: data as Recipe });
      return data as Recipe;
    } catch (err: any) {
      set({ error: err.message });
      return null;
    }
  },

  createRecipe: async (userId, data) => {
    set({ loading: true, error: null });
    try {
      const recipeData = {
        user_id: userId,
        name: data.name,
        description: data.description || null,
        ingredients: data.ingredients,
        instructions: data.instructions,
        prep_time: parseInt(data.prep_time) || 0,
        cook_time: parseInt(data.cook_time) || 0,
        servings: parseInt(data.servings) || 1,
        calories_per_serving: parseInt(data.calories_per_serving) || 0,
        tags: data.tags,
        image_url: null,
        is_template: false,
      };

      const { data: newRecipe, error } = await (supabase as any)
        .from('recipes')
        .insert(recipeData)
        .select()
        .single();

      if (error) {
        set({ error: error.message, loading: false });
        return { data: null, error: error.message };
      }

      set(state => ({ 
        recipes: [newRecipe as Recipe, ...state.recipes],
        loading: false 
      }));

      return { data: newRecipe as Recipe, error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { data: null, error: err.message };
    }
  },

  updateRecipe: async (id, data) => {
    set({ loading: true, error: null });
    try {
      const updateData: any = { ...data };
      
      // Convert string numbers to integers
      if (data.prep_time) updateData.prep_time = parseInt(data.prep_time);
      if (data.cook_time) updateData.cook_time = parseInt(data.cook_time);
      if (data.servings) updateData.servings = parseInt(data.servings);
      if (data.calories_per_serving) updateData.calories_per_serving = parseInt(data.calories_per_serving);

      const { error } = await (supabase as any)
        .from('recipes')
        .update(updateData)
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      // Update local state
      set(state => ({
        recipes: state.recipes.map(r => 
          r.id === id ? { ...r, ...updateData } as Recipe : r
        ),
        selectedRecipe: state.selectedRecipe?.id === id 
          ? { ...state.selectedRecipe, ...updateData } as Recipe
          : state.selectedRecipe,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  deleteRecipe: async (id) => {
    set({ loading: true, error: null });
    try {
      const { error } = await (supabase as any)
        .from('recipes')
        .delete()
        .eq('id', id);

      if (error) {
        set({ error: error.message, loading: false });
        return { error: error.message };
      }

      set(state => ({
        recipes: state.recipes.filter(r => r.id !== id),
        selectedRecipe: state.selectedRecipe?.id === id ? null : state.selectedRecipe,
        loading: false,
      }));

      return { error: null };
    } catch (err: any) {
      set({ error: err.message, loading: false });
      return { error: err.message };
    }
  },

  filteredRecipes: () => {
    const { recipes, searchQuery, selectedTags } = get();
    
    return recipes.filter(recipe => {
      // Filter by search query
      const matchesSearch = !searchQuery.trim() || 
        recipe.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        recipe.description?.toLowerCase().includes(searchQuery.toLowerCase());
      
      // Filter by tags
      const matchesTags = selectedTags.length === 0 || 
        selectedTags.every(tag => recipe.tags.includes(tag));
      
      return matchesSearch && matchesTags;
    });
  },

  getRecipesByTag: (tag) => {
    const { recipes } = get();
    return recipes.filter(r => r.tags.includes(tag));
  },

  getTemplateRecipes: () => {
    const { recipes } = get();
    return recipes.filter(r => r.is_template);
  },
}));

import jsPDF from 'jspdf';
import type { Patient, Anamnesis, MealPlan, FollowUp } from '@/types';
import { calculateAge, calculateBMI, getBMICategory } from './calculations';

// ============================================
// EXPORTACI├ôN A PDF
// ============================================

const addHeader = (doc: jsPDF, title: string) => {
  doc.setFillColor(0, 0, 0);
  doc.rect(0, 0, 210, 25, 'F');
  
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.text('NUTRIXA', 15, 12);
  
  doc.setFontSize(12);
  doc.setFont('helvetica', 'normal');
  doc.text(title, 15, 20);
  
  doc.setTextColor(0, 0, 0);
};

const addFooter = (doc: jsPDF, pageNumber: number) => {
  const pageHeight = doc.internal.pageSize.height;
  
  doc.setDrawColor(200, 200, 200);
  doc.line(15, pageHeight - 20, 195, pageHeight - 20);
  
  doc.setFontSize(9);
  doc.setTextColor(128, 128, 128);
  doc.text(`P├ígina ${pageNumber}`, 15, pageHeight - 12);
  doc.text(`Generado el ${new Date().toLocaleDateString('es-ES')}`, 195, pageHeight - 12, { align: 'right' });
};

// ============================================
// EXPORTAR ANAMNESIS A PDF
// ============================================

export const exportAnamnesisToPDF = (
  patient: Patient, 
  anamnesis: Anamnesis,
  filename?: string
): void => {
  const doc = new jsPDF();
  let y = 35;
  let pageNumber = 1;
  
  addHeader(doc, 'Anamnesis Nutricional');
  
  // Patient info
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text(`${patient.first_name} ${patient.last_name}`, 15, y);
  y += 8;
  
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(`Edad: ${calculateAge(patient.birth_date)} a├▒os | Sexo: ${patient.gender === 'male' ? 'Masculino' : patient.gender === 'female' ? 'Femenino' : 'Otro'}`, 15, y);
  y += 6;
  
  if (patient.email) {
    doc.text(`Email: ${patient.email}`, 15, y);
    y += 6;
  }
  
  if (patient.phone) {
    doc.text(`Tel├®fono: ${patient.phone}`, 15, y);
    y += 6;
  }
  
  y += 10;
  
  // Section helper
  const addSection = (title: string, content: string | string[]) => {
    if (y > 250) {
      addFooter(doc, pageNumber);
      doc.addPage();
      pageNumber++;
      y = 25;
    }
    
    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.text(title, 15, y);
    y += 8;
    
    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    
    if (Array.isArray(content)) {
      content.forEach(line => {
        if (y > 270) {
          addFooter(doc, pageNumber);
          doc.addPage();
          pageNumber++;
          y = 25;
        }
        doc.text(`ÔÇó ${line}`, 20, y);
        y += 6;
      });
    } else {
      const lines = doc.splitTextToSize(content, 170);
      lines.forEach((line: string) => {
        if (y > 270) {
          addFooter(doc, pageNumber);
          doc.addPage();
          pageNumber++;
          y = 25;
        }
        doc.text(line, 20, y);
        y += 6;
      });
    }
    
    y += 4;
  };
  
  // Anthropometric Data
  const bmi = anamnesis.anthropometric_data.bmi;
  const bmiCategory = getBMICategory(bmi);
  
  addSection('Datos Antropom├®tricos', [
    `Peso: ${anamnesis.anthropometric_data.weight} kg`,
    `Altura: ${anamnesis.anthropometric_data.height} cm`,
    `IMC: ${bmi} (${bmiCategory.label})`,
    ...(anamnesis.anthropometric_data.waist_circumference ? [`Circunferencia de cintura: ${anamnesis.anthropometric_data.waist_circumference} cm`] : []),
    ...(anamnesis.anthropometric_data.hip_circumference ? [`Circunferencia de cadera: ${anamnesis.anthropometric_data.hip_circumference} cm`] : []),
    ...(anamnesis.anthropometric_data.body_fat_percentage ? [`% Grasa corporal: ${anamnesis.anthropometric_data.body_fat_percentage}%`] : []),
  ]);
  
  // Consultation Reason
  addSection('Motivo de Consulta', anamnesis.consultation_reason || 'No especificado');
  
  // Physical Activity
  if (anamnesis.physical_activity) {
    addSection('Actividad F├¡sica', [
      `Nivel: ${anamnesis.physical_activity.level}`,
      ...(anamnesis.physical_activity.activities?.length ? [`Actividades: ${anamnesis.physical_activity.activities.join(', ')}`] : []),
      ...(anamnesis.physical_activity.frequency ? [`Frecuencia: ${anamnesis.physical_activity.frequency}`] : []),
      ...(anamnesis.physical_activity.duration ? [`Duraci├│n: ${anamnesis.physical_activity.duration}`] : []),
    ]);
  }
  
  // Diseases
  if (anamnesis.diseases?.length) {
    addSection('Enfermedades', anamnesis.diseases);
  }
  
  // Medications
  if (anamnesis.medications?.length) {
    addSection('Medicaci├│n', anamnesis.medications.map(m => 
      `${m.name}${m.dosage ? ` - ${m.dosage}` : ''}${m.frequency ? ` (${m.frequency})` : ''}`
    ));
  }
  
  // Family History
  if (anamnesis.family_history?.length) {
    addSection('Antecedentes Familiares', anamnesis.family_history.map(fh => 
      `${fh.condition}${fh.relationship ? ` (${fh.relationship})` : ''}`
    ));
  }
  
  // Eating Habits
  if (anamnesis.eating_habits) {
    const habits = [];
    if (anamnesis.eating_habits.meal_frequency) {
      habits.push(`Frecuencia de comidas: ${anamnesis.eating_habits.meal_frequency}`);
    }
    if (anamnesis.eating_habits.cooking_methods?.length) {
      habits.push(`M├®todos de cocci├│n: ${anamnesis.eating_habits.cooking_methods.join(', ')}`);
    }
    if (anamnesis.eating_habits.food_preferences?.length) {
      habits.push(`Preferencias: ${anamnesis.eating_habits.food_preferences.join(', ')}`);
    }
    if (anamnesis.eating_habits.food_dislikes?.length) {
      habits.push(`Alimentos que rechaza: ${anamnesis.eating_habits.food_dislikes.join(', ')}`);
    }
    if (anamnesis.eating_habits.allergies?.length) {
      habits.push(`Alergias: ${anamnesis.eating_habits.allergies.join(', ')}`);
    }
    if (anamnesis.eating_habits.intolerances?.length) {
      habits.push(`Intolerancias: ${anamnesis.eating_habits.intolerances.join(', ')}`);
    }
    
    if (habits.length) {
      addSection('H├íbitos Alimentarios', habits);
    }
  }
  
  // 24h Recall
  if (anamnesis.recall_24h) {
    const recallLines = [];
    
    if (anamnesis.recall_24h.weekday) {
      recallLines.push('D├¡a de semana:');
      Object.entries(anamnesis.recall_24h.weekday).forEach(([key, value]) => {
        if (value) recallLines.push(`  ${key}: ${value}`);
      });
    }
    
    if (anamnesis.recall_24h.weekend) {
      recallLines.push('Fin de semana:');
      Object.entries(anamnesis.recall_24h.weekend).forEach(([key, value]) => {
        if (value) recallLines.push(`  ${key}: ${value}`);
      });
    }
    
    if (recallLines.length) {
      addSection('Recordatorio 24h', recallLines);
    }
  }
  
  // Lab Results
  if (anamnesis.lab_results?.length) {
    addSection('An├ílisis Cl├¡nicos', anamnesis.lab_results.map(lr => 
      `${lr.test_name}: ${lr.value} ${lr.unit}${lr.reference_range ? ` (Ref: ${lr.reference_range})` : ''}`
    ));
  }
  
  addFooter(doc, pageNumber);
  
  const defaultFilename = `anamnesis_${patient.last_name}_${patient.first_name}_${new Date().toISOString().split('T')[0]}.pdf`;
  doc.save(filename || defaultFilename);
};

