export const exportMealPlanToPDF = (
  patient: Patient,
  mealPlan: MealPlan,
  filename?: string
): void => {
  const doc = new jsPDF();
  let y = 35;
  let pageNumber = 1;
  
  addHeader(doc, 'Plan de Alimentaci├│n');
  
  // Patient info
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text(`${patient.first_name} ${patient.last_name}`, 15, y);
  y += 8;
  
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(`Edad: ${calculateAge(patient.birth_date)} a├▒os`, 15, y);
  y += 6;
  
  // Plan info
  y += 4;
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text(mealPlan.name, 15, y);
  y += 8;
  
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  
  if (mealPlan.description) {
    const descLines = doc.splitTextToSize(mealPlan.description, 170);
    descLines.forEach((line: string) => {
      doc.text(line, 15, y);
      y += 6;
    });
  }
  
  y += 4;
  doc.text(`Calor├¡as diarias: ${mealPlan.daily_calories} kcal`, 15, y);
  y += 6;
  doc.text(`Macronutrientes: Prote├¡nas ${mealPlan.macros.protein}% | Carbohidratos ${mealPlan.macros.carbs}% | Grasas ${mealPlan.macros.fats}%`, 15, y);
  y += 6;
  doc.text(`Per├¡odo: ${new Date(mealPlan.start_date).toLocaleDateString('es-ES')} ${mealPlan.end_date ? `al ${new Date(mealPlan.end_date).toLocaleDateString('es-ES')}` : ''}`, 15, y);
  y += 12;
  
  // Days
  const dayNames = ['Lunes', 'Martes', 'Mi├®rcoles', 'Jueves', 'Viernes', 'S├íbado', 'Domingo'];
  
  mealPlan.days.forEach((day, index) => {
    if (y > 230) {
      addFooter(doc, pageNumber);
      doc.addPage();
      pageNumber++;
      y = 25;
    }
    
    doc.setFillColor(240, 240, 240);
    doc.rect(15, y - 5, 180, 10, 'F');
    
    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.text(dayNames[index], 20, y);
    y += 12;
    
    if (day.meals.length === 0) {
      doc.setFontSize(10);
      doc.setFont('helvetica', 'italic');
      doc.setTextColor(128, 128, 128);
      doc.text('Sin comidas asignadas', 20, y);
      doc.setTextColor(0, 0, 0);
      y += 8;
    } else {
      day.meals.forEach(meal => {
        if (y > 260) {
          addFooter(doc, pageNumber);
          doc.addPage();
          pageNumber++;
          y = 25;
        }
        
        doc.setFontSize(11);
        doc.setFont('helvetica', 'bold');
        doc.text(`${meal.name} (${meal.time})`, 20, y);
        y += 6;
        
        doc.setFontSize(10);
        doc.setFont('helvetica', 'normal');
        
        if (meal.recipes.length === 0) {
          doc.text('Sin recetas asignadas', 25, y);
          y += 6;
        } else {
          meal.recipes.forEach(recipe => {
            doc.text(`ÔÇó ${recipe.recipe_name} - ${recipe.quantity} ${recipe.unit}`, 25, y);
            y += 5;
          });
        }
        
        if (meal.notes) {
          doc.setFont('helvetica', 'italic');
          doc.setTextColor(128, 128, 128);
          const noteLines = doc.splitTextToSize(`Nota: ${meal.notes}`, 160);
          noteLines.forEach((line: string) => {
            doc.text(line, 25, y);
            y += 5;
          });
          doc.setTextColor(0, 0, 0);
          doc.setFont('helvetica', 'normal');
        }
        
        y += 4;
      });
    }
    
    y += 8;
  });
  
  addFooter(doc, pageNumber);
  
  const defaultFilename = `plan_alimentacion_${patient.last_name}_${patient.first_name}_${new Date().toISOString().split('T')[0]}.pdf`;
  doc.save(filename || defaultFilename);
};

